const e=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"کەرەستەیێن خوەپاراستنێ (PPE)",subtitle:"Personal Protective Equipment",summary:"ناسینا کەرەستەیێن خوەپاراستنێ و بکارئینانا وان یا دروست",blocks:[{body:"کەرەستەیێن خوەپاراستنا کەسی (PPE) دوماهیک هێلا بەرگریێ نە دژی برینداربوونێ: بەری وان، دڤێت مەترسی ب ڕێکێن ئەندازیاری و ڕێکارێن کاری بهێتە لادان یان کێمکرن (Hierarchy of Controls). ل کارگەهان بکارئینانا PPE نە دلخوازییە، بەلکو فەرزە."},{heading:"١. جۆرێن سەرەکی یێن PPE",body:"بۆ هەر ئەندامەکێ لەشی کەرەستەیەکێ تایبەت هەیە:",points:["سەر: کلاوێ پاراستنێ (Hard Hat) — پاراستن دژی کەفتنا تشتان و لێدانێ.","چاڤ: بەرچاڤکێن سەلامەتیێ (Safety Glasses) — پاراستن دژی تۆز، ماددەیێن کیمیایی، و پریشکان.","گوهـ: گوهگر (Earmuffs / Earplugs) — دژی دەنگێ بلند یێ ئامێران (٨٥ dB(A) و پتر).","دەست: دەستکێش — دژی بڕین، گەرمی، و ماددەیێن کیمیایی.","پێ: پێلاڤێن سەلامەتیێ ب سەرێ ئاسنی (Steel Toe) — دژی پەلچقین و کەفتنا تشتێن گران.","لەش: جلێن ئاشکرا (Hi-Vis) ب ڕەنگێن گەش — دا شوفێر و کارگەرێن دی تە ببینن."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"PPE",description:"ڕێکا دروست یا لبەرکرنێ"}],quiz:[{question:"ل دویڤ ستانداردێن ئەورووپی، کەنگی بکارئینانا گوهگران فەرز دبیت؟",options:[{text:"٥٠ dB",correct:!1},{text:"٧٠ dB",correct:!1},{text:"٨٥ dB(A) و پتر (تێکڕایا ٨ دەمژمێرێن کاری)",correct:!0},{text:"١٢٠ dB",correct:!1}],explanation:"ل دویڤ ڕێنمایا ئەورووپی 2003/10/EC، دەمێ تێکڕایا دەنگی د ٨ دەمژمێرێن کاری دا دگەهیتە ٨٥ dB(A)، دڤێت گوهگر بهێنە بکارئینان. OSHA ژی ل ٨٥ dBA بەرنامەیێ پاراستنا گوهان داخواز دکەت."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سەلامەتیا ئامێران",subtitle:"Machine Safety & Guarding",summary:"پاراستنا کارگەران ژ پشکێن ئامێران یێن کو دلڤن",blocks:[{body:"ئامێرێن پیشەسازی خودان هێزەکا مەزنن و دشێن د چرکەیەکێ دا برینێن گران یان ژدەستدانا ئەندامەکێ لەشی پەیدا بکەن."},{heading:"١. گاردێن ئامێران (Machine Guards)",body:"دڤێت ئەڤ پاراستنە ل سەر هەمی ئامێرێن مەترسیدار هەبن:",points:["گاردێن جێگیر: بۆ داپۆشینا قایش و گێرێن کو دلڤن.","دوگمەیا ڕاوەستاندنا تەنگاڤیێ (E-Stop): دڤێت نێزیکی دەستێ کارگەری بیت و ب ڕەنگێ سۆر ل سەر بنەکێ زەرد بیت.","سێنسۆرێن ڕاوەستاندنێ: ئامێر دوەستیت ئەگەر دەست یان لەش نێزیکی جهێ مەترسیدار ببیت."]},{heading:"٢. ڕێسایێن زێڕین",body:"بەری کاری و ل دەمێ کاری:",points:["چ جاران گاردێ ئامێری لانەدە دەمێ ئامێر کار دکەت.","جلێن شل، زنجیر، و ئەنگوستیلان لبەر نەکە و پرچا درێژ گرێبدە، دا د ئامێری دا نەئێنە گرتن.","ئەگەر ئامێر تێکچوو، ئێکسەر ب دوگمەیا E-Stop ڕاوەستینە و بێی ڕێکارا LOTO دەستێ خوە نەکە ناڤ ئامێری."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"گاردێن ئامێران",description:"نموونەیا گاردەکێ دروست"}],quiz:[{question:"ئەرێ دروستە گاردێ ئامێری بهێتە لادان دەمێ ئامێر کار دکەت؟",options:[{text:"بەلێ، ئەگەر پێدڤی بوو",correct:!1},{text:"نەخێر، ب چ شێوەیان دروست نینە",correct:!0},{text:"تەنێ بۆ پاقژکرنێ",correct:!1},{text:"هەمی بەرسڤ دروستن",correct:!1}],explanation:"لادانا گاردێ ئامێری دەمێ ئامێر کار دکەت ئێک ژ مەترسیدارترین ڕەفتارانە. پاقژکرن و چاککرن تەنێ پشتی ڕاوەستاندن و قوفلکرنا ئامێری (LOTO) دهێنە کرن."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"سەلامەتیا کارەبێ",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مەترسیێن کارەبێ و سیستەمێ قوفلکرن و نیشانکرنێ (LOTO)",blocks:[{body:"کارەبا ل کارگەهان ب ڤۆلتێجەکا بلند کار دکەت؛ لێدانا کارەبێ دشێت ببیتە ئەگەرێ مرنێ یان سووتنێن گران."},{heading:"١. سیستەمێ قوفلکرن و نیشانکرنێ (Lockout/Tagout — LOTO)",body:"ئەڤە گرنگترین ڕێکارە بەری چاککرن یان پاقژکرنا ئامێران:",points:["قوفلکرن (Lockout): سەرچاڤێ کارەبێ یێ سەرەکی ببڕە و قوفلەکێ کەسی لێ بدە.",'نیشانکرن (Tagout): کارتەکێ پێڤە بکە کو ل سەر هاتبیتە نڤیسین: "کار ل سەر دهێتە کرن — هەلنەکە"، دگەل ناڤێ تە و مێژوویێ.',"کلیل تەنێ ل دەستێ وی کەسی بیت یێ چاککرنێ دکەت؛ و بەری دەستپێکرنێ پشتڕاست بە کو ئامێر ب ڕاستی بێ وزەیە (Verify)."]},{heading:"٢. پشکنینا کێبلان",body:"هەمیشە بپشکنە:",points:["کێبلێن بڕی یان یێن تێلێن وان دیار بکار نەئینە.","کارەبا و ئاڤ دوژمنێن هەڤن؛ ل جهێن تەڕ ئامێرێن کارەبێ بکار نەئینە."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"LOTO",description:"چەوا قوفلێ بکار دئینین؟"}],quiz:[{question:"مەبەست ژ LOTO چییە؟",options:[{text:"پاقژکرن",correct:!1},{text:"بڕین و قوفلکرنا وزەیێ بەری چاککرنێ",correct:!0},{text:"زێدەکرنا لەزا ئامێری",correct:!1},{text:"چ ژ ڤان نینە",correct:!1}],explanation:"سیستەمێ LOTO دهێتە بکارئینان دا کو کەسەک کارەبێ ڤەنەکەت دەمێ کارگەر ل سەر ئامێری کار دکەت (OSHA 29 CFR 1910.147)."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"تەمرینکا ئاگری — ڕاهێنانا تەمام",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینا جۆرێن تەمرینکان، پۆلێن ئاگری، و ڕێکارا PASS ب درێژی",blocks:[{body:"تەمرینکا ئاگری (Fire Extinguisher) ئامێرەکێ سەرەکییە بۆ ڤەمراندنا ئاگرێن بچووک د قۆناغا دەستپێکێ دا. ل کارگەهان هەر کارمەندەک دڤێت بزانیت چەوا ب لەز و ب دروستی تەمرینکێ بکاربینیت. زانینا جۆرێن تەمرینکان و پۆلێن ئاگری دێ ژیانا تە و هەڤالێن تە پارێزیت. تەمرینکا دەستی تەنێ چەند چرکەیان کار دکەت، ژبەرهندێ دڤێت ب دروستی بهێتە ئاراستەکرن. ئەگەر ئاگر مەزن بوو یان دوکێل زێدە بوو، تەمرینکێ بهێلە، دەرکەڤە، و گازی ١١٥ بکە."},{heading:"١. پۆلێن ئاگری ل دویڤ NFPA (Fire Classes)",body:"ل دویڤ سیستەمێ ئەمریکی (NFPA)، ئاگر بۆ ٥ پۆلان دابەش دبیت و هەر پۆلەک پێدڤی ب تەمرینکەکا گونجای هەیە. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F.",points:["پۆلا A (تشتێن ڕەق): دار، کاغەز، قوماش، پلاستیک. تەمرینک: ئاڤ، کەف، تۆزا ABC.","پۆلا B (شلەمەنی و غازێن سووتەنێ): بەنزین، نەفت، ڕۆن، ئەلکهول، غاز. شلەمەنی: CO₂، تۆزا ABC یان کەف؛ بۆ ئەلکهولێ و شلەمەنیێن جەمسەری (polar solvents) یێن دی: CO₂، تۆزا هشک یان کەفا بەرگرێ ئەلکهولێ (AR foam)، چونکو کەفا ئاسایی ل سەر وان تێک دچیت. غاز: ئێکەم جار غازێ ڕاوەستینە ئەگەر سەلامەت بیت؛ چ جاران ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی غازێ ڕاوەستینی. (چ جاران ئاڤێ بکار نەئینە!)","پۆلا C (ئامێرێن کارەبێ یێن کارەبا تێدا): سویچ، ترانسفۆرمەر، تابلۆ، جەنەڕەیتەر. تەمرینک: CO₂، تۆزا ABC، Clean Agent. (ئاڤ و کەفێ بکار نەئینە ئەگەر ل سەر لایبلێ پۆلا C یان نیشانا تاقیکرنا کارەبێ نەبیت، وەک هندەک تەمرینکێن ئاڤا هوور (water mist)!)","پۆلا D (کانزا): کانزایێن سووتەنێ — مەگنیسیۆم، تیتانیۆم، سۆدیۆم، و تۆزا ئەلەمنیۆمێ. تەمرینک: تەنێ تەمرینکەکا پۆلا D یان ماددەیەک یێ کو ناڤێ وی کانزای ل سەر لایبلا وی هاتی؛ ماددە ژ کانزایەکێ بۆ یێ دی جودایە. (ئاڤ دشێت تەقینێ چێبکەت!)","پۆلا K (مەتبەخ): ڕۆن و دۆهنێن خوارنپێژانێ. تەمرینک: Wet Chemical. (ئاڤ ڕۆنێ داخ بەلاڤ دکەت!) — ل EN 2 ئەڤە پۆلا F ە."]},{heading:"٢. جۆرێن تەمرینکان ل کارگەهان",body:"ڕەنگ نە پۆلا ئاگری یە. ل دویڤ BS EN 3، لەشێ تەمرینکێ سۆرە؛ ل بەریتانیا پارچەیەکا ڕەنگکری (BS 7863) ماددێ نیشان ددەت. وەلاتێن دی ڕەنگێن دی بکار دئینن و ڕەنگێن د دهۆکێ دا هێشتا نەهاتینە پشتڕاستکرن، لەوا هەمیشە لایبلێ و نیشانێن پۆلێ بخوینە. پۆلێن خوارێ ب پیتێن NFPA نە:",points:["تەمرینکا ئاڤێ (Water): تەمام سۆر، بێ پارچەیا ڕەنگکری — تەنێ بۆ پۆلا A (دار، کاغەز). چ جاران بۆ کارەبێ یان ڕۆنی بکار نەئینە!","تەمرینکا CO₂: پارچەیا ڕەش ل بەریتانیا — بۆ پۆلا B و ئامێرێن کارەبێ یێن کارەبا تێدا (B و C ل دویڤ NFPA؛ ل دویڤ EN 2، C غازە و CO₂ بۆ ئاگرێن غازێ نینە). غازەکا گەلەک سار دەردکەڤیت و لۆلە (Horn) گەلەک سار دبیت؛ تەنێ دەسکی بگرە و چ جاران دەست ب لۆلێ نەگرە، دێ دەستێ تە ب سەرمایێ سۆژیت! دووراتیا CO₂ کێمە و نە بۆ ئاگرێن کویر یێن دار و کاغەزی یە: ژ وێ دووراتیێ دەستپێبکە یا ل سەر لایبلا وێ هاتی و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە. ل ژوورێن بچووک پشتی بکارئینانێ دەرکەڤە و هەوای بگوهۆڕە، چونکو CO₂ ئۆکسجینێ کێم دکەت.","تەمرینکا تۆزا ABC (Dry Powder): پارچەیا شین ل بەریتانیا — بۆ پۆلێن A، B، و C (نە بۆ D و K). بەلاڤترین جۆرە. تۆزەکا سپی دەردکەڤیت؛ کێماسی: دیتنێ کێم دکەت و ئامێران پیس دکەت.","تەمرینکا کەفێ (Foam/AFFF): پارچەیا کرێمی ل بەریتانیا — بۆ پۆلێن A و B. کەفێ ل سەر شلەمەنیێ ڕادخەت و ئۆکسجینێ ژێ دبڕیت. بۆ کارەبێ بکار نەئینە!","تەمرینکا Clean Agent: پۆلێن وێ ل دویڤ مۆدێلێ جودانە، لەوا لایبلێ بخوینە (گەلەک جاران B و C ب پیتێن NFPA؛ هندەک مۆدێل بۆ A ژی) — بۆ ئامێرێن هەستیار و ژوورێن سێرڤەران. پاشماوە ناهێلیت و زیانێ ناگەهینیتە ئامێرێن ئەلکترۆنی.","تەمرینکا تایبەت (Class D): بۆ کانزایێن سووتەنێ ل کارگەهان — دڤێت ناڤێ وی کانزایێ ل وێرێ بکار دهێت ل سەر لایبلا وێ هاتبیت. چ جاران ئاڤێ ل کانزایێ سووتەنێ نەکە!"]},{heading:"٣. ڕێکارا PASS — ب درێژی",body:"بەری تو تەمرینکێ بکار بینی، دڤێت هەمی بەرسڤ «بەلێ» بن: ئاگر بچووک و تازە دەستپێکری بیت، تەمرینک گونجای بیت، ڕێکا دەرکەفتنێ ل پشت تە بیت، ئاگەهداری هاتبیتە دان و گازی ١١٥ هاتبیتە کرن، تو ڕاهێنان دیتی بی، و چو دوکێل یان گەرمی ڕێکا تە نەگریت. ئەگەر ئاگر ئێکسەر ڤەنەمری، دەرکەڤە و دەرگەهی بگرە. PASS ڕێکارا گشتی یە بۆ پتریا تەمرینکێن دەستی؛ تەمرینکێن Class D، Wet Chemical، Clean Agent و یێن ل سەر چەرخان: ل دویڤ لایبلێ و ڕێنمایێن کۆمپانیا دروستکەر بکار بینە:",points:["P = Pull (بکێشە): مێخا سەلامەتیێ (Safety Pin) بکێشە. ئەڤ مێخە ناهێلیت تەمرینک ب خەلەتی کار بکەت.","A = Aim (ئاراستە بکە): لۆلا تەمرینکێ ئاراستەی بنێ ئاگری بکە — نە سەرێ گڕێ! سووتەمەنیا ئاگری ل بنی یە.","S = Squeeze (فشار بدە): دەسکێن تەمرینکێ ب هێز فشار بدە دا کو ماددە دەرکەڤیت.","S = Sweep (بلڤینە): لۆلێ ب چەپ و ڕاست ل سەر بنێ ئاگری بلڤینە هەتا ئاگر ب تەمامی ڤەدمریت؛ پاشان چاڤدێریا جهی بکە دا ئاگر دووبارە هەلنەبیت."]},{heading:"٤. پشکنینا هەیڤانە یا تەمرینکان",body:"پشکنینا ب چاڤ هەر هەیڤەکێ، ژ لایێ کەسێ بەرپرس ڤە (NFPA 10):",points:["فشارا ناڤ تەمرینکێ (Pressure Gauge)، ئەگەر هەبیت: دڤێت مێلک ل ناڤ دەڤەرا کەسک بیت. تەمرینکێن CO₂ پیڤەرا فشارێ نینە: هەلگرە دا هەست بکەی کو تژی یە.","مێخا سەلامەتیێ و مۆرا وێ: دڤێت ل جهێ خوە بن و نەهاتبنە شکاندن.","لۆلە (Nozzle): نابیت شکەستی یان گرتی بیت.","لەشێ تەمرینکێ: نابیت ژەنگی، قلیشی، یان زیانلێکەفتی بیت.","کارتا پشکنینێ و لایبل: دڤێت مێژوویا پشکنینا دوماهیێ ل سەر کارتێ بیت؛ لایبل بهێتە خواندن و ڕوویێ وێ بەرەڤ دەرڤە بیت؛ تەمرینک ل جهێ خوە بیت، دیار بیت و ب ساناهی بگەهیتێ.","تێبینی: ئەڤان ژێک جودا بکە. پشکنین و ساخکرنا سالانە ژ لایێ کەسەکێ شارەزا ڤە؛ تژیکرنەڤە (Recharge) پشتی هەر بکارئینانەکێ، هەتا ئەگەر کورت ژی بیت؛ ساخکرنا ٦ سالان: تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی (stored-pressure) یێن کو پێدڤی ب تاقیکرنا هیدرۆستاتیکی یا ١٢ سالان هەی، هەر ٦ سالان جارەکێ ڤالا دکەن و ناڤا وان دپشکنن؛ تاقیکرنا هیدرۆستاتیکی (Hydrostatic Test، تاقیکرنا فشارێ یا لەشێ وێ) هەر ٥ سالان بۆ تەمرینکێن ئاڤێ، کەفێ (AFFF)، CO₂ و تۆزا هشک یا ستێنلێس ستیل (stainless steel)، و هەر ١٢ سالان بۆ تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی یێن لەشێ وان ژ ئاسنێ نەرم (mild steel)، مسێ زەرد یێ لحیمکری (brazed brass) یان ئەلەمنیۆمێ. دەمێ تاقیکرنێ نە دەمێ گوهۆڕینێ یە. ڕێسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن."]},{heading:"٥. مەترسیێن تایبەت ل کارگەهان",body:"کارگەهـ جهەکێ هەستیارە ژبەر ڤان ئەگەران:",points:["ماددەیێن کیمیایی: سۆلڤێنت، ئەلکهول، تینەر — هەمی پۆلا B نە.","کارەبا ب ڤۆلتێجا بلند: تابلۆ و ترانسفۆرمەر — پۆلا C (NFPA).","تۆزا داری و ئاردی: ل هندەک کارگەهان دشێت تەقینا تۆزێ (Dust Explosion) پەیدا بکەت.","لەحیمکرن و بڕین: پریشکێن لەحیمکرنێ دشێن ئاگرێن پۆلێن A و B پەیدا بکەن.","کۆگەها سووتەمەنیێ: دڤێت ل ژوورەکا تایبەت یان ل دەرڤەی ئاڤاهی بیت، و تەمرینکا گونجای (کەف یان تۆز) نێزیک بیت.","جهێ دانانێ: تەمرینکان نێزیکی دەرگەه و ڕێڕەوان دانە؛ دووراتیا گەهشتنێ بۆ تەمرینکا پۆلا A نابیت ژ ٢٣ مەتران (٧٥ پێ) پتر بیت، و بۆ شلەمەنیان ٩-١٥ مەتر (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"تەمرینکا ئاگری ل کارگەهان",description:"ڕێکارا PASS و جۆرێن تەمرینکان ب ڤیدیۆ"}],quiz:[{question:"ب پیتێن NFPA، تەمرینکا CO₂ بۆ کیش پۆلێن ئاگری گونجایە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییێن سووتەنێ (B) و ئامێرێن کارەبێ (C) گونجایە، چونکو پاشماوە ناهێلیت و کارەبێ ناگوهێزیت. ل دویڤ EN 2، C ئاگرێن غازێ نە و CO₂ بۆ وان نینە."},{question:"ل ڕێکارا PASS، دڤێت لۆلا تەمرینکێ بەرەڤ کیڤە بیت؟",options:[{text:"سەرێ گڕێ",correct:!1},{text:"بنێ ئاگری",correct:!0},{text:"دوور ژ ئاگری",correct:!1},{text:"بانێ ژووری",correct:!1}],explanation:"هەمیشە لۆلێ بەرەڤ بنێ ئاگری بکە، چونکو سووتەمەنیا ئاگری ل وێرێ یە."},{question:"بۆچی ئاڤ ل سەر ئاگرێ ڕۆنی (پۆلا K) ناهێتە ڕژاندن؟",options:[{text:"چ تشتەکی ناکەت",correct:!1},{text:"ئاڤ ڕۆنێ سووتی بەلاڤ دکەت و گڕەکا مەزن پەیدا دکەت",correct:!0},{text:"ڕۆن ئاڤێ دخۆت",correct:!1},{text:"ئاڤ ب خوە دسوژیت",correct:!1}],explanation:"ئاڤ ل سەر ڕۆنێ داخ ئێکسەر دکەلیت و ڕۆنێ سووتی ب هەوا دئێخیت، و گڕەکا مەزن (Fireball) پەیدا دبیت. تەمرینکا Wet Chemical یان سەرپۆشەکێ بکاربینە و گەرمیێ ببڕە."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"هەوارهاتنا ئێکێ و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانا تەمام ل سەر هەوارهاتنا ئێکێ، CPR، و هەلسوکەفتێ ل دەمێ تەنگاڤیێ ل کارگەهان",blocks:[{body:"هەوارهاتنا ئێکێ (First Aid) ئەو هاریکاریا دەستپێکێ یە یا کو بەری گەهشتنا تیمێن پزیشکی دهێتە دان بۆ کەسێ بریندار یان نەخۆش. ل کارگەهان مەترسیا برینداربوونێ گەلەک یا بلندە — ژ بڕین و سووتنێ هەتا لێدانا کارەبێ و کەفتنا ژ جهێن بلند. هەر کارمەندەک دڤێت بزانیت چەوا گازی ئەمبوولانسێ (١٢٢) بکەت، CPR بکەت، خوینبەربوونێ ڕاگریت، و برینداری بپارێزیت هەتا ئەمبوولانس دگەهیت. ئەڤ وانەیە ل دویڤ ڕێنمایێن AHA 2025 و Stop the Bleed هاتیە ئامادەکرن."},{heading:"١. فشارا سنگی و هەناسەدان (CPR) — ب درێژی",body:"CPR ڕێکارەکا ڕزگارکرنا ژیانێ یە دەمێ دلێ مرۆڤی دوەستیت و هەناسەدانا ئاسایی نامینیت. ل دویڤ ڤان هەنگاڤان کار بکە:",points:["١. سەلامەتیا جهی: بەری هەر تشتەکی پشتڕاست بە کو جه سەلامەتە (کارەبا، ئاگر، یان غاز نینن)، دا تو نەبیە قوربانیا دووێ.",'٢. بەرسڤدان: ملێن برینداری ب هێز بهەژینە و ب دەنگەکێ بلند بپرسە: "تو باشی؟ تو من دبهیزی؟".',"٣. گازیکرن: ئەگەر بەرسڤ نەدا و هەناسە نەدا یان تەنێ هەناسێن نە ئاسایی دان، ئێکسەر گازی ١٢٢ بکە (یان کەسەکی بدە گازیکرنێ) و بخوازە ئامێرێ AED بهێتە ئینان.","٤. فشارێن سنگی (Compressions): پاژنا دەستەکێ بدانە ناڤەڕاستا سنگی (نیڤا خوارێ یا هەستیێ سنگی) و دەستێ دی بدانە سەر. ٣٠ فشارێن ب هێز و ب لەز بدە: کویراتی ٥-٦ سم، لەز ١٠٠-١٢٠ فشار د خولەکەکێ دا، و بهێلە سنگ ب تەمامی بزڤڕیت.","٥. هەناسەدان: سەری بەرەڤ پاش ببە و چەناکێ بلند بکە، دفنێ بگرە و ٢ هەناسەیان بدە (هەر ئێک نێزیکی ١ چرکە، هەتا سنگ بلند دبیت). ئەگەر نەشێی یان نەڤێی هەناسەیان بدەی، تەنێ فشارێن سنگی بەردەوام بکە.","٦. بەردەوامی (٣٠:٢): بەردەوام بە ل سەر ٣٠ فشاران و ٢ هەناسەیان هەتا ئەمبوولانس دگەهیت، AED ئامادە دبیت، یان بریندار دەست ب هەناسەدانا ئاسایی دکەت.","٧. بکارئینانا AED: ئێکسەر کو گەهشت، ڤەکە، پەدان (Pads) ب سنگێ ڕووت ڤە بنووسینە و فەرمانێن دەنگی یێن ئامێری جێبەجێ بکە؛ دەمێ شۆک دهێتە دان دەست ل برینداری نەدە."]},{heading:"٢. کۆنترۆلکرنا خوینبەربوونێ (Stop the Bleed)",body:"خوینبەربوونا توند دشێت د دەمەکێ کورت دا مرۆڤی بکوژیت، ژبەرهندێ گازی ١٢٢ بکە و ب لەز ڤان هەنگاڤان بکە:",points:["فشارا ڕاستەوخۆ: پارچەکا قوماشێ پاقژ بدانە سەر برینێ و ب هەردوو دەستان ب هێز فشار بدە. ئەگەر قوماش ب خوینێ تژی بوو، لانەدە؛ پارچەکا دی ل سەر بدانە و فشارێ بەردەوام بکە.","تژیکرنا برینێ (Wound Packing): ئەگەر برین کویر بوو (وەک ل ڕان، بن مل، یان ستۆی)، قوماشێ پاقژ یان گازا خوینڕاگر د ناڤ برینێ دا بتژینە و ب هێز فشار بدە. ئەندامێ بریندار بلند نەکە و ل خالێن فشارێ (Pressure Points) نەگەڕە.","تۆرنیکە (Tourniquet): ئەگەر خوینبەربوونا دەست یان پێی مەترسیا ژیانێ هەبوو، ب زوویی تۆرنیکێ ٥-٧ سم ل سەر برینێ (بەرەڤ لەشی) ب قایمی ببەستە، دەمی بنڤیسە، و چ جاران سست نەکە.","تشتێ چەقی: ئەگەر ئاسن یان شووشە د ناڤ برینێ دا چەقی بوو، چ جاران دەرنەئینە! دێ خوینبەربوونێ زێدە کەت. ل دۆرا وی فشارێ بدە و جێگیر بکە."]},{heading:"٣. چارەسەرکرنا سووتنێ",body:"سووتن ل کارگەهان مەترسیدارە؛ ب ڤی ڕەنگی مامەلێ دگەل بکە، و بۆ سووتنێن مەزن یان ل ڕوو و دەستان گازی ١٢٢ بکە:",points:["سووتنا گەرمیێ: ئێکسەر ئاڤا فێنک یا ڕەوان (نە ئاڤا سەهۆلێ) بۆ ماوێ ٢٠ خولەک ب سەر سووتنێ دا بڕژینە. ئەنگوستیلک و دەمژمێرێ ب زوویی ڤەکە بەری کو ئەندام بوەرمیت.","سووتنا کیمیایی: جلێن پیس ڤەکە و پێستی ب ئاڤەکا گەلەک یا ڕەوان بۆ ماوێ ٢٠ خولەک یان پتر بشۆ، و وەرەقا SDS یا ماددەی بپشکنە.","سووتنا کارەبێ: ئێکەم کار کارەبێ ببڕە! پاشان سووتنێ وەک سووتنا گەرمیێ سار بکە و گازی ١٢٢ بکە، چونکو کارەبا دشێت زیانێ ب دلی و ناڤ لەشی بگەهینیت.","ئاگەهداری: بلقێن سووتنێ نەتەقینە، و سەهۆل، دۆهن، مەعجوونا ددانان، یان مەرهەمێن بێ ڕێنمایا پزیشکی بکار نەئینە."]},{heading:"٤. شکەستن و بریندارییێن ستوینا پشتێ",body:"ل دەمێ کەفتنا ژ جهێن بلند یان گومانا شکەستنێ:",points:["جێگیرکرن (Splinting): ئەگەر گومانا شکەستنێ هەبوو، ئەندامێ بریندار نەلڤینە. وەک کو هەی، ب دارەکێ یان کارتۆنەکێ جێگیر بکە دا ئێش کێم ببیت.","پاراستنا پشت و ستۆی: ئەگەر کەسەک ژ جهەکێ بلند کەفت، نەلڤینە مەگەر جه مەترسیدار بیت (وەک ئاگر)، چونکو لڤاندن دشێت ببیتە ئەگەرێ ئیفلیجبوونێ. سەری جێگیر بگرە و گازی ١٢٢ بکە.","سارکرن: بۆ کێمکرنا وەرمێ (Swelling)، سەهۆلێ د پارچە قوماشەکێ دا بپێچە و بۆ ماوێ ٢٠ خولەک بدانە سەر جهێ ئێشانێ؛ سەهۆلێ ڕاستەوخۆ نەدانە سەر پێستی."]},{heading:"٥. لێدانا کارەبێ و ڕزگارکرن",body:"کارەبا دشێت دلی ڕاوەستینیت؛ ڤان ڕێکاران جێبەجێ بکە:",points:["ئێکسەر کارەبێ ببڕە: هەتا کارەبا نەهێتە بڕین دەست ل برینداری نەدە، چونکو کارەبا دێ تە ژی گریت.","جوداکرنا سەلامەت: ئەگەر نەشیای کارەبێ ببڕی و ڤۆلتێج نزم بوو، ب دارەکێ هشک یان پلاستیکی تێلێ ژ برینداری دوور بێخە و ل سەر تشتەکێ هشک ڕاوەستە. نێزیکی هێلێن ڤۆلتێج بلند نەبە و گازی ١١٥ بکە.","پشکنینا پزیشکی: هەمی کەسێن کارەبا لێدای، حەتا ئەگەر هەست ب باشیێ بکەن ژی، دڤێت بچنە نەخۆشخانێ بۆ پشکنینا دلی؛ گازی ١٢٢ بکە."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"CPR و هەوارهاتنا ئێکێ",description:"ڕاهێنانا CPR و هاریکاریا برینداران ل کارگەهان"}],quiz:[{question:"د CPR دا، دڤێت لەزا فشارێن سنگی د خولەکەکێ دا چەند بیت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠+",correct:!1}],explanation:"ل دویڤ AHA 2025، لەزا فشاران ١٠٠-١٢٠ فشار د خولەکەکێ دا یە، ب کویراتیا ٥-٦ سم بۆ مەزنان، دا خوین بگەهیتە مێشکی."},{question:"ئەگەر تشتەکێ تیژ د ناڤ برینێ دا چەقی بوو، دێ چ کەی؟",options:[{text:"دەردئینم",correct:!1},{text:"ل جهێ خوە دهێلم و گازی ١٢٢ دکەم",correct:!0},{text:"دەستێ خوە ژێ دوور دئێخم و چ ناکەم",correct:!1},{text:"ب ئاڤێ دشۆم",correct:!1}],explanation:"دەرئینانا تشتی دێ خوینبەربوونێ زێدە کەت. دڤێت ل جهێ خوە بمینیت و جێگیر بهێتە کرن هەتا پزیشک ل نەخۆشخانێ دەردئینیت."},{question:"ئەگەر کارەبا ل کەسەکی دابیت، ئێکەم کارێ تو دکەی چییە؟",options:[{text:"دەستێ وی دگرم",correct:!1},{text:"CPR دکەم",correct:!1},{text:"کارەبێ دبڕم",correct:!0},{text:"ئاڤێ ب سەر دا دکەم",correct:!1}],explanation:"دڤێت ئێکەم جار سەرچاڤێ کارەبێ بهێتە بڕین دا کارەبا تە ژی نەگریت؛ پاشان گازی ١٢٢ بکە و ئەگەر پێدڤی بوو دەست ب CPR بکە."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"ماددەیێن کیمیایی (SDS)",subtitle:"Chemical Safety & Labelling",summary:"مامەلەکرن دگەل ماددەیێن کیمیایی و ناسینا مەترسیێن وان",blocks:[{body:"ماددەیێن کیمیایی ل کارگەهان دشێن ببنە ئەگەرێ سووتنا پێستی، ژەهراویبوونێ، ئاگری، یان تەقینێ."},{heading:"١. وەرەقا SDS چییە؟",body:"وەرەقا زانیاریێن سەلامەتیێ (Safety Data Sheet — SDS) زانیاریێن هەر ماددەیەکی د ١٦ پشکان دا ددەت، ژ وان:",points:["پێکهاتەیا ماددەی و مەترسیێن وی.","کیش PPE پێدڤییە (ماسک، دەستکێش، بەرچاڤک).","هەوارهاتنا ئێکێ ئەگەر ماددە بەر لەشی کەفت، و ڕێکێن ڤەمراندنا ئاگری."]},{heading:"٢. هێمایێن GHS",body:"هندەک ژ نیشانێن ل سەر قوتی و عەلبان:",points:["گڕ (Flame): ماددەیێ سووتەنێ.","کەلەسەر و هەستی (Skull and Crossbones): ماددەیێ ژەهراوی یێ کوژەر.","خوارن (Corrosion): ماددەیێ ئاسیدی یان ئەلکالی کو پێست و کانزایان دخوت."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"SDS",description:"نیشانێن مەترسیێ یێن GHS"}],quiz:[{question:"ل کیڤە دشێین بزانین کا کیش ماسک بۆ ماددەیەکێ کیمیایی پێدڤییە؟",options:[{text:"ل نیشانێن سەر دیواری",correct:!1},{text:"د وەرەقا SDS دا",correct:!0},{text:"ژ هەڤالێ خوە بپرسە",correct:!1},{text:"پێدڤی ب ماسکێ نینە",correct:!1}],explanation:"وەرەقا SDS هەمی زانیاریێن پاراستنێ یێن تایبەت ب وی ماددەی ددەت، ژ وان جۆرێ PPE یێ پێدڤی (پشکا ٨)."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"کارکرن ل جهێن بلند",subtitle:"Fall Protection & Ladders",summary:"ڕێگرتن ل کەفتنێ ژ داربەست، بان، و پەیژەیان",blocks:[{body:"کەفتنا ژ جهێن بلند ئێک ژ ئەگەرێن سەرەکی یێن مرنێ یە ل کارگەه و جهێن ئاڤاهیسازیێ."},{heading:"١. پاراستن دژی کەفتنێ",body:"هەر کارەکێ ل بلندیێ (OSHA: ژ ١٫٢ مەتران ل کارگەهان و ژ ١٫٨ مەتران ل ئاڤاهیسازیێ) پێدڤی ب ڤان تشتانە:",points:["هارنەس (Full Body Harness): ب دروستی و ب قایمی لبەرکرن.","تێلا سەلامەتیێ (Lanyard): دڤێت ب خالەکا گرێدانێ یا قایم (Anchor Point) ڤە بیت.","ڕێلێن پاراستنێ (Guardrails): ل دۆرا داربەست، بان، و لێڤێن ڤەکری."]},{heading:"٢. سەلامەتیا پەیژێ (Ladders)",body:"ڕێسایا ٣ خالێن پێگرتنێ:",points:["هەمیشە دڤێت ٣ ئەندامێن لەشی (دوو پێ و دەستەک، یان دوو دەست و پێیەک) ل سەر پەیژێ بن.","گۆشەیا دانانا پەیژێ دڤێت ٤:١ بیت (بۆ هەر ٤ مەترێن بلندیێ، بنێ پەیژێ مەترەکێ ژ دیواری دوور بیت)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"کارکرن ل بلندیێ",description:"بکارئینانا هارنەسی"}],quiz:[{question:"ڕێسایا ٣ خالان ل سەر پەیژێ واتە چییە؟",options:[{text:"٣ کەس پێکڤە ل سەر بن",correct:!1},{text:"٣ خولەک ل سەر بمینە",correct:!1},{text:"هەمیشە ٣ ئەندامێن لەشی ب پەیژێ ڤە بن",correct:!0},{text:"پەیژێ ب ٣ تێلان ببەستە",correct:!1}],explanation:"ڕێسایا ٣ خالان بۆ هندێ یە کو کارگەر هەڤسەنگیا خوە ژ دەست نەدەت و نەکەڤیت."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"جهێن تەنگ و داخستی",subtitle:"Confined Space Safety",summary:"کارکرن د ناڤ تانک، بۆری، و مەنهۆلان دا",blocks:[{body:"جهێن داخستی مەترسیدارن چونکو هەوا تێدا ناهێتە گوهۆڕین، ئۆکسجین دشێت کێم ببیت، و غازێن کوژەر تێدا کۆم دبن."},{heading:"١. مەترسیێن سەرەکی",body:"بەری تو بچیە ژوور، بزانە:",points:["کێمیا ئۆکسجینێ (کێمتر ژ ١٩٫٥٪): دبیتە ئەگەرێ خەندقینێ.","غازێن ژەهراوی وەک CO (بێ بێهن) و H₂S (کو ل چڕیێن بلند هەستا بێهنێ ڕادگریت).","مەترسیا ئاگر و تەقینێ ئەگەر غاز یان هەلمێن سووتەنێ هەبن."]},{heading:"٢. ڕێکارێن چوونا ژوورێ",body:"دڤێت ئەڤ مەرجە هەبن:",points:["پشکنینا هەوای ب ئامێرێ پیڤانا غازێ (Gas Monitor) بەری چوونێ و ل دەمێ کاری.","هەبوونا چاڤدێرەکی (Attendant) کو ل دەرڤە بمینیت، چاڤێ وی ل کارگەرێ ژوورێ بیت، و ب چ ڕەنگان نەچیتە ژوور.","مۆلەتا کاری (Permit)، ئامرازێن پەیوەندیێ، و پلانا ڕزگارکرنێ دڤێت ئامادە بن."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"جهێن داخستی",description:"پشکنینا هەوای"}],quiz:[{question:"ئەرێ دروستە چاڤدێرێ دەرڤە بێی ئامێر بچیتە ژوور بۆ ڕزگارکرنا هەڤالێ خوە؟",options:[{text:"بەلێ، ژبەر مرۆڤاتیێ",correct:!1},{text:"نەخێر، چونکو ئەو ژی دێ خەندقیت",correct:!0},{text:"بەلێ، ئەگەر هەناسا خوە بگریت",correct:!1},{text:"چ ژ ڤان نینە",correct:!1}],explanation:"ل دویڤ لێکۆلینێن NIOSH، بەشەکێ مەزن ژ مرنێن جهێن داخستی ئەو کەسن یێن بێی ئامێر و ڕاهێنان چوویینە ژوور بۆ ڕزگارکرنێ. چاڤدێر دڤێت گازی تیما ڕزگارکرنێ و ١١٥ بکەت."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"دەنگ و پاراستنا گوهان",subtitle:"Hearing Conservation",summary:"پاراستن دژی دەنگەدەنگا ئامێرێن مەزن",blocks:[{body:"کەڕبوون یان کێمبوونا بهیستنێ ژبەر دەنگێ کارگەهان هێدی هێدی چێدبیت و چارەسەر نابیت."},{heading:"١. ئاستێن دەنگی",body:"کەنگی دەنگ دبیتە مەترسی؟",points:["٨٥ dB(A): سنوورێ دەستپێکرنا مەترسیێ بۆ ٨ دەمژمێرێن کاری.","١٠٠ dB(A): بێی پاراستن تەنێ بۆ ١٥ خولەک د ڕۆژێ دا سەلامەتە (NIOSH).","نیشانە: ئەگەر پشتی کاری تە هەست ب زڕەزڕێ (Tinnitus) د گوهێن خوە دا کر، دەنگ گەلەک بلند بوویە."]},{heading:"٢. کەرەستەیێن پاراستنێ",body:"کەرەستەیێن پاراستنا گوهان (Hearing Protection Devices — HPD):",points:["گوهگرێن ناڤ گوهی (Earplugs): ئەگەر ب دروستی بهێنە دانان، پاراستنەکا باش ددەن.","گوهگرێن سەر گوهی (Earmuffs): ب هێسانی دهێنە لبەرکرن و بۆ دەنگێن بلند گونجاینە.","بکارئینانا هەردووکان پێکڤە ل جهێن گەلەک ب دەنگ."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"دەنگ",description:"چەوا گوهگران بکار دئینی؟"}],quiz:[{question:"ئەگەر دەنگ گەهشتە ١٠٠ dB(A)، ل دویڤ NIOSH چەند دەم دشێی بێی گوهگر بمینی؟",options:[{text:"١ دەمژمێر",correct:!1},{text:"١٥ خولەک",correct:!0},{text:"٤ دەمژمێر",correct:!1},{text:"هەمی ڕۆژێ",correct:!1}],explanation:"ل دویڤ NIOSH، هەر ٣ dB زێدەبوون دەمێ سەلامەت دکەتە نیڤ: ٨٥ dB(A) بۆ ٨ دەمژمێران، و ١٠٠ dB(A) تەنێ بۆ ١٥ خولەک."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"هەلگرتنا باران (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"ڕێگرتن ل ئێشانا پشتێ و ماسوولکەیان",blocks:[{body:"برینداربوونا پشتێ ئێک ژ بەلاڤترین برینانە ل کارگەهان، ژبەر هەلگرتنا خەلەت یا باران."},{heading:"١. ڕێکارا دروست یا هەلگرتنێ",body:"جێبەجێکرنا ڤان هەنگاڤان پشتێ دپارێزیت:",points:["چۆکێن خوە بچەمینە: هێزا پێیان بکاربینە، نە یا پشتێ.","باری نێزیکی لەشی بکە: هندی بار ژ تە دوورتر بیت، فشار ل سەر پشتێ زێدەتر دبیت.","پشتا خوە ڕاست ڕاگرە: دەمێ تشتەکێ گران هەلدگری، پشتا خوە نەچەمینە.","لەشێ خوە نەبادە: ئەگەر تە ڤیا باری بەرەڤ لایەکی ببەی، ب پێیان ب هەمی لەشی ڤە بزڤڕە."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"هەلگرتنا باری",description:"شێوازێ دروست"}],quiz:[{question:"ل دەمێ هەلگرتنا تشتەکێ گران، دڤێت هێز ل سەر چ بیت؟",options:[{text:"پشت",correct:!1},{text:"ماسوولکەیێن پێیان",correct:!0},{text:"مل",correct:!1},{text:"تەنێ دەست",correct:!1}],explanation:"ماسوولکەیێن پێیان ب هێزترن و پشتێ ژ برینداربوونێ دپارێزن."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"غاز و هەواگوهۆڕین",subtitle:"Ventilation & Toxic Gases",summary:"کۆنترۆلکرنا هەوای و غازێن ژەهراوی",blocks:[{body:"هەواگوهۆڕینا دروست ل کارگەهێ گرنگە بۆ ڕێگرتن ل کۆمبوونا تۆز و غازێن کو دبنە ئەگەرێ نەخۆشیێن هەناسێ."},{heading:"١. مۆنۆکسیدا کاربۆنێ (CO)",body:"غازا کوژەر یا بێدەنگ:",points:["بێ ڕەنگ و بێ بێهنە.","ژ سووتنا سووتەمەنیێ و مەکینەیێن بەنزین و دیزلێ (وەک جەنەڕەیتەر و فۆرکلیفت) پەیدا دبیت.","نیشانە: سەرئێشان، گێژبوون، دلتێکهاتن، و بێهۆشبوون. ئەگەر هەست ب ڤان نیشانان کر، ئێکسەر دەرکەڤە دەرڤە و گازی ١٢٢ بکە."]},{heading:"٢. جۆرێن هەواگوهۆڕینێ",body:"چەوا هەوا دهێتە گوهۆڕین؟",points:["هەواگوهۆڕینا سرۆشتی: دەرگەه و پەنجەرێن ڤەکری.","هەواگوهۆڕینا دەستکرد: فەن و سیستەمێن ڕاکێشانا هەوای (Local Exhaust).","پاراستنا کەسی: ماسکێن فلتەردار ل دویڤ SDS؛ بەلێ ماسکێن فلتەری دژی CO و کێمیا ئۆکسجینێ ناپارێزن."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"غاز",description:"غازا CO"}],quiz:[{question:"بۆچی غازا CO مەترسیدارە؟",options:[{text:"چونکو بێهنا وێ خرابە",correct:!1},{text:"چونکو ناهێتە دیتن و بێهنکرن",correct:!0},{text:"چونکو ڕەنگێ وێ سۆرە",correct:!1},{text:"چونکو تەنێ ب شەڤ پەیدا دبیت",correct:!1}],explanation:"ژبەر کو هەست پێ ناهێتە کرن، کارگەر بێی کو بزانن ژەهراوی دبن. ئامێرێن ناسینا CO (CO Detector) ل وان جهان دانە یێن مەکینە لێ کار دکەن."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"دەرکەفتنا لەزگین (Evacuation)",subtitle:"Emergency Assembly Points",summary:"پلانا چوونا دەرڤە ل دەمێ ئاگری یان کارەساتێ",blocks:[{body:"زانینا ڕێکا دەرکەفتنێ دشێت جوداهیێ د ناڤبەرا ژیان و مرنێ دا بکەت."},{heading:"١. ڕێسایێن دەرکەفتنێ",body:"دەمێ زەنگا مەترسیێ لێدەت:",points:["ب هێمنی و ب لەز بمەشە، نەڕەڤە، و ئەسانسۆرێ بکار نەئینە.","دەرگەهان ل پشت خوە بگرە دا ئاگر و دوکێل بەلاڤ نەبن، بەلێ قوفل نەکە.","بەرەڤ خالا کۆمبوونێ (Assembly Point) بچە دا ژمارا کارمەندان بهێتە کرن.","ب چ ڕەنگان نەزڤڕە ژوور هەتا بەرپرسێ سەلامەتیێ یان تیمێن ١١٥ ڕێ نەدەن."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"تەمرینا دەرکەفتنێ",description:"ڕاهێنانا دەرکەفتنێ"}],quiz:[{question:"دەمێ زەنگا مەترسیێ لێدەت، دێ چ کەی؟",options:[{text:"کۆمکرنا کەرەستەیێن خوە",correct:!1},{text:"ب هێمنی بەرەڤ دەرکەفتنێ چوون",correct:!0},{text:"خوە ل بن مێزێ ڤەشارتن",correct:!1},{text:"هاوارکرن",correct:!1}],explanation:"دەرکەفتنا ب هێمنی و ب لەز باشترین ڕێکارە بۆ پاراستنا ژیانێ."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سەلامەتیا لەحیمکرنێ",subtitle:"Welding & Cutting Hazards",summary:"پاراستن ژ تیشک، گەرمی و دوکێلا لەحیمکرنێ",blocks:[{body:"کارێ لەحیمکرنێ مەترسیا تیشکێن سەرووبنەفشی (UV)، سووتنێن گران، و غاز و دوکێلێن ژەهراوی تێدایە."},{heading:"١. پاراستنا چاڤان و پێستی",body:"پێدڤیێن لەحیمکاران:",points:["کلاوێ پاراستنێ یێ لەحیمکرنێ (Welding Helmet) ب فلتەرێ گونجای: بۆ پاراستنا چاڤان ژ تیشکێن UV و ڕۆناهیا توند یا قەوسا لەحیمکرنێ (Arc).","دەستکێشێن چەرمی یێن درێژ: بۆ پاراستن ژ گەرمی و پریشکان.","بەروانکا چەرمی (Apron): بۆ پاراستنا لەشی."]},{heading:"٢. مەترسیا ئاگری (Hot Work)",body:"بەری دەستپێکرنێ مۆلەتا کارێ گەرم (Hot Work Permit) وەربگرە و:",points:["دۆرا جهێ کاری ژ ماددەیێن سووتەنێ پاقژ بکە (NFPA 51B: ب دووراتیا ١١ مەتران / ٣٥ پێ)، یان ب پەردێن بەرگری داپۆشە.","تەمرینکەکا گونجای ل نێزیک خوە ئامادە بکە.","چاڤدێرێ ئاگری (Fire Watch): ل دەمێ کاری و کێمترین ١ دەمژمێر پشتی ب دوماهیک هاتنا کاری ل جهی بمینیت؛ پاشان جه هەتا ٣ دەمژمێرێن دی دهێتە چاڤدێریکرن، ل دویڤ بڕیارا بەرپرسێ مۆلەتێ (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"لەحیمکرن",description:"لبەرکرنا دروست"}],quiz:[{question:"بۆچی پشتی لەحیمکرنێ چاڤدێرێ ئاگری کێمترین ١ دەمژمێر ل جهی دمینیت؟",options:[{text:"بۆ پاقژکرنێ",correct:!1},{text:"دا ئاگرەکێ ڤەشارتی پەیدا نەبیت",correct:!0},{text:"بۆ سارکرنا ئاسنی",correct:!1},{text:"چ پێدڤی نینە",correct:!1}],explanation:"گەلەک جاران پریشک دکەڤنە ناڤ قلیش و کەرەستەیان و پشتی دەمەکی ئاگری پەیدا دکەن. ل دویڤ NFPA 51B (چاپا ٢٠١٩ و پشتی هنگێ)، چاڤدێری کێمترین ١ دەمژمێر پشتی کاری بەردەوام دبیت."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"ئامێرێن ڤەگوهاستنێ",subtitle:"Forklift & Vehicle Safety",summary:"سەلامەتیا فۆرکلیفتێ و ئاژۆتنێ ل کارگەهێ",blocks:[{body:"فۆرکلیفت ئامێرەکێ گرانە و مەترسیا پەلچقاندنێ و وەرگەڕیانێ هەیە ئەگەر ب دروستی نەهێتە ئاژۆتن."},{heading:"١. ڕێسایێن ئاژۆتنێ",body:"بۆ شوفێرێن فۆرکلیفتێ:",points:["تەنێ کەسێن ڕاهێنای و مۆلەتدار دشێن فۆرکلیفتێ بئاژۆن (OSHA 1910.178).","چ جاران کەسەکی ل سەر شاخێن (Forks) فۆرکلیفتێ یان ل کێلەکا خوە هەلنەگرە.","بار ژ کاپاسیتیا ئامێری زێدەتر نەکە دا وەرنەگەڕیت، و پشتوێنا سەلامەتیێ گرێبدە.","ل هەر کونجەکێ یان دەرگەهەکێ لەزێ کێم بکە و هۆرنێ (Horn) لێبدە."]},{heading:"٢. سەلامەتیا پیادەیان",body:"ئەگەر تو ل نێزیک فۆرکلیفتێ دمەشی:",points:["چاڤێ تە ل شوفێری بیت (Eye Contact) و دووراتیەکا سەلامەت بهێلە.","د ڕێڕەوێن نیشانکری یێن پیادەیان دا بمەشە."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"فۆرکلیفت",description:"ناسینا خالێن نەدیار (Blind Spots)"}],quiz:[{question:"ئەگەر شوفێرێ فۆرکلیفتێ بارەکێ بلند هەبیت و پێشیا خوە نەبینیت، دێ چ کەت؟",options:[{text:"ب لەز بئاژۆت",correct:!1},{text:"ب پاشڤە (Reverse) بئاژۆت",correct:!0},{text:"هۆرنێ لێبدەت و چاڤێن خوە بگریت",correct:!1},{text:"چ ژ ڤان نینە",correct:!1}],explanation:"دەمێ بار دیتنا شوفێری دگریت، دڤێت ب پاشڤە بئاژۆت دا ڕێکا خوە ببینیت (OSHA 1910.178)."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"نیشانێن سەلامەتیێ",subtitle:"Safety Signs & Symbols",summary:"ناسینا ڕەنگ و هێمایێن سەلامەتیێ (ISO 7010)",blocks:[{body:"نیشانێن سەلامەتیێ ب زمانەکێ جیهانی ئاگەهداریێ ل سەر مەترسیان ددەنە مە."},{heading:"١. واتایا ڕەنگان (ISO 7010)",body:"هەر ڕەنگەک پەیامەکا تایبەت دگەهینیت:",points:["سۆر: قەدەغەکرن یان ئامێرێن ئاگرکوژیێ (نموونە: جگارەکێشان قەدەغەیە).","زەرد: ئاگەهداری و مەترسی (نموونە: مەترسیا کارەبێ).","شین: فەرز (نموونە: دڤێت کلاوێ پاراستنێ لبەر بکەی).","کەسک: سەلامەتی و دەرکەفتن (نموونە: دەرگەهێ دەرکەفتنێ)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"نیشانێن سەلامەتیێ",description:"هێمایێن ستاندارد"}],quiz:[{question:"نیشانەکا ب ڕەنگێ زەرد واتە چییە؟",options:[{text:"قەدەغەکرن",correct:!1},{text:"ئاگەهداری و مەترسی",correct:!0},{text:"جهێ سەلامەت",correct:!1},{text:"بکارئینانا ئاڤێ",correct:!1}],explanation:'ڕەنگێ زەرد هەمیشە واتە "ئاگەهدار بە" یان "مەترسی هەیە".'}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"پاقژی (Housekeeping)",subtitle:"Order & Maintenance",summary:"ڕێکخستنا جهێ کاری بۆ کێمکرنا مەترسیان",blocks:[{body:"جهێ کاری یێ پاقژ جهەکێ سەلامەتە. گەلەک ڕووداو ژبەر خلیسکین و کەفتنا ب سەر کەرەستەیێن بەلاڤ دا ڕوودەن."},{heading:"١. ڕێسایێن گشتی",body:"بۆ هەمی کارگەران:",points:["پاقژکرنا ڕۆن یان ئاڤا ڕژای ب زووترین دەم.","کۆمکرنا پاشماوەیان د سەلکێن تایبەت دا.","هێلانا ڕێڕەو و دەرکەفتنان ڤەکری و بێ ئاستەنگ.","زڤڕاندنا هەر ئامێرەکی بۆ جهێ وی پشتی ب دوماهیک هاتنا کاری."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"پاقژی",description:"نموونەیا جهەکێ پاقژ"}],quiz:[{question:"ئەگەر تە دیت ڕۆن ل سەر عەردی ڕژایە، دێ چ کەی؟",options:[{text:"دهێلم هەتا پاقژکەر دهێت",correct:!1},{text:"پاقژ دکەم یان نیشانەکێ لێ ددانم و ئاگەهدار دکەم",correct:!0},{text:"ب سەر دا باز ددەم",correct:!1},{text:"گوهـ نادەمێ",correct:!1}],explanation:"هەر کارگەرەک بەرپرسە ژ پاقژی و سەلامەتیا جهێ کارێ خوە، دا کەس نەکەڤیت."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"عەردەهەژین ل کارگەهان",subtitle:"Earthquake Safety in Factories",summary:"سەلامەتیا کارگەران ل دەمێ عەردەهەژینێ و پشتی وێ",blocks:[{body:"عەردەهەژین ل کارگەهان مەترسیەکا دووقات پەیدا دکەت: هەم هەژینا ب خوە، و هەم کەفتنا ئامێرێن گران، ڕژانا ماددەیێن کیمیایی، شکەستنا بۆریان، و دزەکرنا غازێ. دڤێت هەر کارگەهەک پلانەکا عەردەهەژینێ هەبیت."},{heading:"١. خوە بدە عەردی، خوە بپارێزە، خوە بگرە (Drop, Cover, Hold On)",body:"ل دەمێ عەردەهەژینێ:",points:["خوە بدە عەردی (Drop) و بچە بن مێزەکێ یان مێزا کاری (Workbench) یا قایم — دوور ژ ئامێرێن گران، ڕەفان، و شووشەیان.","ئەگەر مێز نەبوو، ل نک دیوارەکێ ناڤخوەیی ب چۆکان ڕوینە و سەر و ستۆیێ خوە ب دەستان داپۆشە (Cover).","ب مێزێ ڤە بگرە (Hold On) هەتا هەژین ب تەمامی دوەستیت.","نەڕەڤە و نەچە بن ئامێران یان نک ڕەفان! ئامێرێن گران و ڕەف دشێن بلڤن یان بکەڤنە سەر تە."]},{heading:"٢. پشتی عەردەهەژینێ",body:"پشتی هەژین دوەستیت:",points:["ئامێران بۆ زیانێ بپشکنە، و ئامێرێن زیانلێکەفتی هەلنەکە هەتا بهێنە پشکنین.","ببینە کا ماددەیێن کیمیایی ڕژاینە یان نە، و ژ وان دوور بکەڤە.","ئەگەر بێهنا غازێ هات — ب لەز دەرکەڤە، کارگەهێ ڤالا بکە، و ژ دەرڤە گازی ١١٥ بکە.","غازێ تەنێ ببڕە ئەگەر بێهنا وێ هات یان دەنگێ دزەکرنێ هات؛ کارەبێ ببڕە ئەگەر زیان ب تێل یان تابلۆیان گەهشتبیت.","بەری زڤڕینا ژوور، دڤێت ئەندازیارەک ئاڤاهیێ کارگەهێ بۆ قلیشان بپشکنیت."]},{heading:"٣. ئامادەبوون",body:"پلانا پێشوەخت:",points:["بۆ هەر پشکەکێ پلانا عەردەهەژینێ ئامادە بکە.","ئامێرێن گران ب زنجیر یان بۆلتان جێگیر بکە.","دەبە و قوتیێن کیمیایی ل سەر ڕەفێن نزم و جێگیر دانە.","ڕێڕەوێن دەرکەفتنێ هەمیشە ڤەکری بن.","هەر ٦ هەیڤان جارەکێ تەمرینێ بکە."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"عەردەهەژین",description:"عەردەهەژین ل کارگەهێ"}],quiz:[{question:"ل دەمێ عەردەهەژینێ ل کارگەهەکێ، ئێکەم کار چییە؟",options:[{text:"ڕەڤین بەرەڤ دەرڤە",correct:!1},{text:"خوە بدە عەردی و بچە بن مێزەکێ قایم",correct:!0},{text:"ئامێران ڤەمرینە",correct:!1},{text:"بچە نێزیکی پەنجەرەیان",correct:!1}],explanation:"خوە بدە عەردی، خوە بپارێزە، خوە بگرە — ئێکەم ڕێکارە ل ناڤ ئاڤاهیان، دوور ژ ئامێر، ڕەف، و شووشەیان."},{question:"پشتی عەردەهەژینێ ل کارگەهەکا کیمیایی، ئێکەم پشکنین چییە؟",options:[{text:"کارەبا",correct:!1},{text:"ڕژانا ماددەیێن کیمیایی",correct:!0},{text:"ئاڤ",correct:!1},{text:"تەلەفۆن",correct:!1}],explanation:"ڕژانا ماددەیێن کیمیایی مەترسیەکا مەزنە پشتی عەردەهەژینێ و پێدڤییە ب لەز بهێتە پشکنین."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"لافاو و ئاڤبەربوون",subtitle:"Flood Emergency in Industrial Areas",summary:"پاراستنا کارگەه و کارگەران ل دەمێ لافاوێ",blocks:[{body:"لافاو دشێت کارگەهان ب تەمامی وێران بکەت: ئامێران خراب بکەت، ماددەیێن کیمیایی بەلاڤ بکەت، و کارەبێ بکەتە مەترسی. کارگەهێن نێزیکی ڕووبار و گەلیان پتر د مەترسیێ دانە."},{heading:"١. بەری لافاوێ",body:"ئامادەبوون:",points:["ئاگەهدارییێن کەشناسیێ (Meteorology) بشۆپینە.","کەرەستەیێن گرنگ و ماددەیێن کیمیایی بگوهێزە جهەکێ بلند.","سیستەمێ کارەبێ بۆ بڕینا خوەکار (Auto-shutoff) ئامادە بکە.","کیسێن لمێ (Sandbags) ل بەر دەرگەه و بنیاتا کارگەهێ دانە."]},{heading:"٢. ل دەمێ لافاوێ",body:"ڕێکارێن لەزگین:",points:["ئەگەر ب سەلامەتی بشێی و ئاڤ نەگەهشتبیتە تابلۆیێن کارەبێ، کارەبێ و غازێ ببڕە؛ د ناڤ ئاڤێ دا دەست ل کارەبێ نەدە!","نەچە ناڤ ئاڤا لافاوێ — ١٥ سم ئاڤا ب لەز دشێت مرۆڤی بێخیت، و ٣٠ سم دشێت ترومبێلێ ببەت.","بچە جهەکێ بلند — نهۆما دووێ یان سەر بانی.","گازی ١١٥ بکە و ل جهێ خوە بمینە هەتا تیمێن ڕزگارکرنێ دگەهن."]},{heading:"٣. پشتی لافاوێ",body:"زڤڕین و پاقژکرن:",points:["نەچە ناڤ کارگەهێ هەتا ئەندازیار پشتڕاست نەکەت کو ئاڤاهی سەلامەتە.","دەست ل ماددەیێن کیمیایی یێن ئاڤ تێکەفتی نەدە — ب ڕێکا ١١٥ تیما ماددەیێن مەترسیدار (HazMat) بخوازە.","کارەبێ ڤەنەکە هەتا سیستەم ژ لایێ کارەباچیەکێ شارەزا ڤە بهێتە پشکنین.","وێنەیێن هەمی زیانان بگرە بۆ بیمە و ڕاپۆرتێ."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"لافاو",description:"لافاو ل کارگەهێ"}],quiz:[{question:"ل دەمێ لافاوێ ل کارگەهەکێ، ئێکەم کار چییە؟",options:[{text:"ئامێران بپارێزە",correct:!1},{text:"کارەبێ و غازێ ببڕە، ئەگەر ب سەلامەتی بشێی",correct:!0},{text:"بچە مال",correct:!1},{text:"ئاڤێ ب پەمپێ دەربێخە",correct:!1}],explanation:"کارەبا و غاز مەترسیێن ئێکەمن ل دەمێ لافاوێ؛ بەلێ ئەگەر ئاڤ گەهشتبیتە تابلۆیان، نێزیک نەبە و بچە جهەکێ بلند."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"بەرسڤدانا بەرگرییا شارستانی ل کارگەهان",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"پێکهاتنا تیما بەرسڤدانێ یا کارگەهێ ل دەمێ ڕووداوان و هەماهەنگی دگەل ١١٥",blocks:[{body:"کارگەهێن مەزن (نەفت، غاز، کیمیا، پۆلا) دڤێت تیمێن خوە یێن بەرسڤدانا تەنگاڤیێ هەبن کو بەری گەهشتنا تیمێن ١١٥ کار بکەن. ستانداردا NFPA 600 (Facility Fire Brigades) ڕێکخستن، ڕاهێنان، و ئامێرێن تیمێن ئاگرکوژیێ یێن کارگەهان دیار دکەت. خولەکێن ئێکێ یێن ڕووداوی گەلەک گرنگن، ژبەرهندێ تیما کارگەهێ دڤێت ئامادە و ڕاهێنای بیت."},{heading:"١. پێکهاتنا تیما بەرسڤدانێ یا کارگەهێ (ERT)",body:"بنەمایێن سەرەکی یێن تیما بەرسڤدانا تەنگاڤیێ (Emergency Response Team):",points:["قەبارەیا تیمێ: ل دویڤ هەلسەنگاندنا مەترسیێن کارگەهێ و ئەرکێن تیمێ دهێتە دیارکرن؛ NFPA 600 ڕێژەیەکا جێگیر یا ئەندامان بۆ ژمارا کارمەندان دیار ناکەت.","ڕاهێنان: ل دویڤ ئەرکێن هەر ئەندامەکی، دگەل ڕاهێنانا دووبارە (Refresher) ب کێمی سالێ جارەکێ.","فەرماندەرێ ڕووداوی (Incident Commander — IC): تەنێ ئێک کەس فەرمانێ ددەت، دا فەرمان تێکەل نەبن.","ئەرکێن سەرەکی: ڤەمراندنا ئاگری، ڕزگارکرن، هەوارهاتنا ئێکێ، و ڤالاکرنا ئاڤاهی.","پەیوەندی: بێتەل (Radio) ب کەنالەکێ تایبەت، و مۆبایل وەک ڕێکا یەدەگ.","دەمێ بەرسڤدانێ: ل پلانێ دا دیار بکە، ب تەمرینان بپیڤە، و باشتر بکە.","پێشنیار: خولێن ICS-100 و ICS-200 (FEMA) بۆ فێربوونا سیستەمێ فەرماندەریا ڕووداوی."]},{heading:"٢. پلانا بەرسڤدانا تەنگاڤیێ (ERP)",body:"پلانا بەرسڤدانا تەنگاڤیێ (Emergency Response Plan) ل دویڤ ستانداردان:",points:["پلانا کارێ تەنگاڤیێ دڤێت ب نڤیسین بیت و ل کارگەهێ بەردەست بیت؛ کارگەهێن ١٠ کارمەند یان کێمتر دشێن ب دەڤی ڕابگەهینن (OSHA 29 CFR 1910.38).","پشکێن سەرەکی: ئەرک، ڕێکار، ڕێکێن دەرکەفتنێ، پەیوەندی، ژێدەر، تەمرین، و هەلسەنگاندنا پشتی ڕووداوی.","خالێن کۆمبوونێ (Assembly Points): ئێکا سەرەکی و ئێکا یەدەگ، ل جهەکێ سەلامەت و دوور ژ ئاڤاهی و ڕێکا ترومبێلێن تەنگاڤیێ.","ڕێکێن دەرکەفتنێ: ب گشتی کێمترین ٢ ڕێک ژ هەر نهۆمەکێ (NFPA 101، ب هندەک بەدەرکرنان).","زەنگا ئاگری (Alarm): دڤێت ل هەمی جهێن ئاڤاهی بهێتە بهیستن یان دیتن (NFPA 72).","تیما هەوارهاتنا ئێکێ: د هەر دەوامەکێ (Shift) دا کارمەندێن ڕاهێنانا هەوارهاتنا ئێکێ و CPR وەرگرتی هەبن.","تەمرین (Drill): ب ڕێک و پێک، و ئەنجامێن هەر تەمرینەکێ بهێنە تۆمارکرن.","هەلسەنگاندنا پشتی ڕووداوی (Post-Response Critique): ب زووترین دەم پشتی هەر ڕووداوەکی."]},{heading:"٣. هەماهەنگی دگەل بەرگرییا شارستانی (١١٥)",body:"دەمێ ڕووداو چێدبیت و تیمێن ١١٥ دگەهن، دڤێت ERT ڤان هەنگاڤان بکەت:",points:["١. ئێکسەر گازی ١١٥ بکە، و ١٢٢ ئەگەر بریندار هەبن.","٢. زانیاریێن سەرەکی بدە: جه، جۆرێ ڕووداوی، ژمارا برینداران، ماددەیێن مەترسیدار، و ڕێکا گەهشتنێ.","٣. نەخشێ کارگەهێ (Site Map) ل بەر دەرگەهی ئامادە بکە، دگەل جهێن مەترسیێ و جهێن بڕینا کارەبێ و غازێ.","٤. کەسێ پەیوەندیێ (Liaison Officer): تەنێ ئێک کەس پەیوەندیێ دگەل ١١٥ دکەت.","٥. وەرەقێن SDS بۆ هەمی ماددەیێن کیمیایی ئامادە بکە.","٦. ناڤ و گۆتنێن شاهدان تۆمار بکە.","٧. ڤەگوهاستنا فەرمانێ: دەمێ ١١٥ دگەهیت، فەرمان دچیتە دەستێ فەرماندەرێ ١١٥ و ERT هاریکاریێ دکەت.","٨. بەلگەنامە: وێنە، ڤیدیۆ، و تۆمارا ڕووداوی (Incident Log) بۆ لێکۆلینێ و بیمێ."]},{heading:"٤. کارکرن دگەل تیما ماددەیێن مەترسیدار (HazMat)",body:"بۆ ڕووداوێن کیمیایی، تیما HazMat پێدڤییە:",points:["ئاستێن ڕاهێنانا HazMat (OSHA 1910.120 و NFPA 470، کو NFPA 472 تێدا هاتیە کۆمکرن):","• ئاستێ هشیاریێ (Awareness): ناسینا مەترسیێ، دوورکەفتن، و ئاگەهدارکرن — بۆ هەمی کارمەندان.","• ئاستێ کارپێکرنێ (Operations): پاراستنا خەلکی و دەوروبەری ب ڕێکێن بەرگری (Defensive) ژ دوور.","• ئاستێ تەکنیکی (Technician): ڕاگرتنا دزەکرنێ ژ نێزیک (Offensive) ب PPE یا تایبەت.","• ئاستێ پسپۆر (Specialist): زانیاریێن کویر ل سەر ماددەیێن دیارکری و پشتەڤانیا تەکنیکیان.","سێ ناڤچە: ناڤچا گەرم (Hot Zone)، ناڤچا نیڤەگەرم (Warm Zone)، و ناڤچا سار (Cold Zone).","ئاستێن PPE یێن HazMat: A، B، C، D (A بلندترین پاراستنە).","پاقژکرنا پیسبوونێ (Decontamination) ل ناڤچا نیڤەگەرم دهێتە کرن، بەری چوونا ناڤچا سار.","کارمەندێن نەڕاهێنای ناچنە ناڤچا گەرم؛ چاڤەڕێی تیمێن ١١٥ بن.","پلانا کارگەهێ دڤێت دیار بکەت کا تیمێن تایبەت یێن ماددەیێن مەترسیدار چەوا ب ڕێکا ١١٥ دهێنە داخوازکرن."]},{heading:"٥. بەرسڤدانا چەند دەزگەهان پێکڤە (Multi-Agency Response)",body:"ڕووداوێن مەزن پێدڤی ب چەند دەزگەهان دبن:",points:["١١٥ بەرگرییا شارستانی: ڤەمراندنا ئاگری، ڕزگارکرن، و ماددەیێن مەترسیدار.","١٢٢ ئەمبوولانس: چارەسەرکرنا پزیشکی و ڤەگوهاستنا برینداران.","١٠٤ پۆلیس: گرتنا دەوروبەری، هاتوچۆ، و لێکۆلینا یاسایی.","دەزگەهێن ئاسایشێ: ل دەمێ گومانا تەقەمەنیان یان تیرۆرێ — ب ڕێکا ١٠٤ دهێنە ئاگەهدارکرن.","وەزارەتا تەندروستیێ: ئامادەکرنا نەخۆشخانێن نێزیک.","فەرمانگەها کارەبێ: بڕینا کارەبێ ل دەوروبەری.","دەزگەهێن ئاڤێ و غازێ: بڕینا هێلێن ئاڤێ و غازێ.","دەستەیا ژینگەهێ: ئەگەر ماددەیێن کیمیایی د ژینگەهێ دا بەلاڤ بوون.","ناڤەندا کارێن تەنگاڤیێ (EOC): بۆ ڕووداوێن مەزن کو گەلەک دەزگەهـ تێدا بەشدار دبن."]},{heading:"٦. قۆناغێن بەرسڤدانێ (٥ قۆناغ)",body:"هەر ڕووداوەک ب ڤان ٥ قۆناغان دا دبۆریت:",points:["١. ناسین (Detection): سێنسۆر، زەنگا ئاگری، یان شاهد.","٢. ئاگەهدارکرن (Notification): گازیکرنا ١١٥، و ئاگەهدارکرنا ERT و کەسێ پەیوەندیێ.","٣. بەرسڤدان (Response): ERT کار دکەت هەتا تیمێن ١١٥ دگەهن.","٤. کێمکرنا مەترسیێ (Mitigation): ڤەمراندنا ئاگری، ڕزگارکرن، و پاقژکرنا پیسبوونێ.","٥. ڤەگەڕان (Recovery): پاقژکرن، شیکارکرن، و هەلسەنگاندنا پشتی ڕووداوی.","دڤێت هەر قۆناغەک بهێتە تۆمارکرن (Incident Action Plan — IAP).","دەمژمێرا زێڕین (Golden Hour): چارەسەریا لەز پشتی برینداربوونا گران شانسێ ژیانێ زێدە دکەت — ژبەرهندێ گازیکرنا لەز بۆ ١٢٢ گرنگە."]},{heading:"٧. مەشق و ڕاهێنان (Drills & Training)",body:"تەمرین بنەمایێ ئامادەبوونێ یە (خشتەیا پێشنیارکری):",points:["تەمرینا سەر مێزێ (Tabletop Exercise): هەر ٣ هەیڤان جارەکێ — سەناریۆ ل سەر مێزێ.","تەمرینا کاری (Functional Drill): هەر ٦ هەیڤان جارەکێ — تەنێ تیما ERT، نە هەمی ئاڤاهی.","تەمرینا تەمام (Full-Scale Drill): سالێ جارەکێ — هەمی کارگەهـ دگەل ١١٥.","هەلسەنگاندن: ڕاپۆرتا پشتی تەمرینێ (After-Action Report) ب زووترین دەم.","ڕاهێنانا ERT: ب بەردەوامی و ل دویڤ ئەرکان، کێمترین سالێ جارەکێ.","ستانداردێن شارەزاییێ: NFPA 1081 (Facility Fire Brigade Member)، OSHA 1910 Subpart L، و ICS-100/200.","تەمرینا هەڤپشک دگەل ١١٥: سالێ جارەکێ بۆ هەماهەنگیێ."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"تەمرینا بەرسڤدانا ERT",description:"تەمرینا تەمام ل کارگەهەکا نەفتێ"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"پەیکەرێ فەرماندەریا ڕووداوی (ICS)",description:"پەیکەرێ فەرماندەریا ڕووداوی (ICS)"}],quiz:[{question:"قەبارەیا تیما بەرسڤدانا تەنگاڤیێ (ERT) ل کارگەهێ چەوا دهێتە دیارکرن؟",options:[{text:"ب ڕێژەیەکا جێگیر: ١ بۆ ١٠٠ کارمەندان",correct:!1},{text:"ل دویڤ هەلسەنگاندنا مەترسیێن کارگەهێ و ئەرکێن تیمێ",correct:!0},{text:"ب ڕێژەیەکا جێگیر: ١ بۆ ٢٠٠ کارمەندان",correct:!1},{text:"ب ڕێژەیەکا جێگیر: ١ بۆ ٢٥ کارمەندان",correct:!1}],explanation:"NFPA 600 ڕێژەیەکا جێگیر یا ئەندامان بۆ ژمارا کارمەندان دیار ناکەت؛ هەر کارگەهەک ل دویڤ مەترسی و ئەرکێن خوە قەبارەیا تیمێ دیار دکەت."},{question:"دەمژمێرا زێڕین (Golden Hour) چ واتە یە؟",options:[{text:"دەمژمێرەکا تایبەت یا کاری",correct:!1},{text:"دەمێ دەستپێکێ پشتی برینداربوونا گران، کو چارەسەریا لەز تێدا گەلەک گرنگە",correct:!0},{text:"دەمێ نیڤرۆ",correct:!1},{text:"گەرمیا ڕۆژێ",correct:!1}],explanation:"Golden Hour ئەو دەمە یێ پشتی برینداربوونا گران کو گەهاندنا لەز یا برینداری بۆ چارەسەریێ شانسێ ژیانێ زێدە دکەت؛ ژبەرهندێ ئێکسەر گازی ١٢٢ بکە."},{question:"ل سیستەمێ ICS، کەسێ پەیوەندیێ (Liaison Officer) چ کار دکەت؟",options:[{text:"ئاگری ڤەدمرینیت",correct:!1},{text:"پەیوەندیێ دگەل دەزگەهێن دەرڤە دکەت",correct:!0},{text:"CPR دکەت",correct:!1},{text:"دەرگەهی دگریت",correct:!1}],explanation:"کەسێ پەیوەندیێ پەیوەندیێ دگەل ١١٥، پۆلیس (١٠٤)، ئەمبوولانس (١٢٢)، و دەزگەهێن دی دکەت."},{question:"ئاستێ Operations یێ HazMat چ کار دکەت؟",options:[{text:"تەنێ ئاگەهدارکرن",correct:!1},{text:"بەرگری (Defensive) — ڕێگرتنا بەلاڤبوونێ ژ دوور",correct:!0},{text:"Offensive — گرتنا دزەکرنێ ژ نێزیک",correct:!1},{text:"پسپۆری (Specialist)",correct:!1}],explanation:"ئاستێ Operations بەرگرییە (Defensive): ڕێگرتنا بەلاڤبوونا ماددەی ژ دوور، نە کارێ ژ نێزیک (Offensive)."},{question:"ناڤچا گەرم (Hot Zone) ل HazMat چییە؟",options:[{text:"جهەکێ سار و سەلامەت",correct:!1},{text:"ناڤچەکا ب تەمامی پاقژ",correct:!1},{text:"ناڤچا هەرە مەترسیدار — تەنێ تەکنیکیێن HazMat ب PPE یا گونجای",correct:!0},{text:"ناڤچا کۆمبوونێ",correct:!1}],explanation:"ناڤچا گەرم جهێ ماددەیێ مەترسیدارە؛ تەنێ تەکنیکیێن HazMat ب PPE یا ئاستێ A یان B دچنە ناڤ."},{question:"دەمێ تیمێن ١١٥ دگەهنە جهێ ڕووداوی، فەرمان دچیتە دەستێ کێ؟",options:[{text:"ERT بەردەوام دبیت",correct:!1},{text:"فەرماندەرێ ١١٥",correct:!0},{text:"ڕێڤەبەرێ کارگەهێ",correct:!1},{text:"پۆلیس",correct:!1}],explanation:"ڤەگوهاستنا فەرمانێ (ICS Transfer): دەمێ ١١٥ دگەهیت، فەرمان دچیتە دەستێ فەرماندەرێ ١١٥ و ERT هاریکاریێ دکەت."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"پۆلینکرنا ئاگری ل کارگەهان",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"پۆلینکرنا تایبەت بۆ کارگەهان: شلەمەنی، غاز، کانزا، و تۆزا سووتەنێ",blocks:[{body:"ئەڤ مۆدیولە سیستەمێ NFPA بکار دئینیت: A تشتێن ڕەق، B شلەمەنی و غازێن سووتەنێ، C ئامێرێن کارەبێ، D کانزا، K ڕۆنێ مەتبەخێ. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F. ستانداردێن تایبەت ل کارگەهان: شلەمەنییێن سووتەنێ (NFPA 30)، کانزایێن سووتەنێ (NFPA 484)، و تۆزا سووتەنێ (NFPA 654). ژ چاپا ٢٠٢٥ ڤە، NFPA 484 و NFPA 654 د ستانداردا NFPA 660 دا هاتینە کۆمکرن."},{heading:"١. پۆلا A — تشتێن ڕەق یێن سووتەنێ ل کارگەهێ",body:"تشتێن ڕەق یێن بەلاڤ ل کارگەهان:",points:["سووتەمەنی: کاغەز، کارتۆن، قوماش، دار، لاستیک، پلاستیک، و پالێت (Pallets).","ئەڤ ماددە خەلووز و ئاگرێ ڤەشارتی دهێلن؛ پشتی ڤەمراندنێ جهی ب ئاڤێ سار بکە و چاڤدێری بکە.","ل کارگەهان: کۆگەهێن کاغەز و کارتۆنان و پالێتێن داری ئاگری ب لەز بەلاڤ دکەن.","تەمرینک: ئاڤ، کەف، تۆزا ABC.","پالێتێن ڤالا یێن کۆمکری مەترسیەکا مەزنن: ب بلندی کۆم نەکە، و ل دەرڤە یان ل جهەکێ ب سپرینکلەر هەلگرە.","ستاندارد: NFPA 13 (سیستەمێن سپرینکلەری)، کو پاراستنا کۆگەهان ژی تێدایە.","نموونە ل کارگەهان: کۆگەهـ و هێلێن پاکێتکرنێ (Packaging Lines)."]},{heading:"٢. پۆلا B — شلەمەنییێن سووتەنێ ل کارگەهێ",body:"ئێک ژ مەترسیدارترین پۆلان ل کارگەهان:",points:["سووتەمەنی: بەنزین، نەفت، دیزل، ئەسیتۆن (Acetone)، تۆلوین (Toluene)، زایلین (Xylene).","خالا هەلبوونێ (Flash Point): بەنزین نێزیکی -٤٣°C، ئەسیتۆن -٢٠°C، دیزل ٥٢°C یان پتر.","سنوورێن تەقینێ (LEL/UEL): کێمترین و زێدەترین چڕیا هەلمێ د هەوای دا کو دشێت بگریت:","• بەنزین: ١٫٤-٧٫٦٪","• ئەسیتۆن: ٢٫٥-١٢٫٨٪","• میتانۆل (Methanol): ٦-٣٦٪","تەمرینک: کەف (AFFF یان کەفا بێ فلۆرین)، CO₂، تۆزا ABC. بۆ ئەسیتۆن، میتانۆل، ئەلکهول و شلەمەنیێن جەمسەری (polar solvents) یێن دی: CO₂، تۆزا هشک یان کەفا بەرگرێ ئەلکهولێ (AR foam)؛ کەفا ئاسایی ل سەر وان تێک دچیت.","جەتا ئاڤێ ل سەر شلەمەنیێ نەڕژینە — ئاگری بەلاڤ دکەت. BLEVE (Boiling Liquid Expanding Vapor Explosion) دەمێ تانکەکا ب فشار ب ئاگری گەرم دبیت چێدبیت.","پۆلێن شلەمەنیان ل دویڤ NFPA 30 (Flash Point = خالا هەلبوونێ، Boiling Point = خالا کەلینێ):","• Class I (Flammable): خالا هەلبوونێ کێمتر ژ ٣٧٫٨°C — IA (هەلبوون < ٢٢٫٨°C و کەلین < ٣٧٫٨°C)، IB (هەلبوون < ٢٢٫٨°C و کەلین ٣٧٫٨°C یان پتر)، IC (هەلبوون ٢٢٫٨ هەتا < ٣٧٫٨°C).","• Class II (Combustible): خالا هەلبوونێ ٣٧٫٨ هەتا < ٦٠°C.","• Class III (Combustible): IIIA ژ ٦٠ هەتا < ٩٣°C، و IIIB ٩٣°C یان پتر.","دیوارێن ڕاگرتنێ (Diking): ل دویڤ NFPA 30، قەبارەیا جهێ ڕاگرتنێ دڤێت کێمتر نەبیت ژ وێ شلەمەنیا کو ژ مەزنترین تانکا تژی دشێت بڕژیت (١٠٠٪)؛ ڕێژەیا ١١٠٪ ل هندەک یاسا و ڕێنمایێن دی دهێتە خواستن (بۆ ئاڤا بارانێ ژی).","چڕیا هەلمێ (Vapor Density): هەلما بەنزینێ ژ هەوای گرانترە (نێزیکی ٣-٤ جاران) و ل جهێن نزم کۆم دبیت."]},{heading:"٣. غازێن سووتەنێ — NFPA: پۆلا B، EN 2: پۆلا C",body:"غازێن کارگەهان: ئەسیتیلین، پرۆپان، هایدرۆجین:",points:["سەرچاڤە: ئەسیتیلین (Acetylene) بۆ لەحیمکرنێ، پرۆپان (Propane) بۆ هندەک فۆرکلیفتان، هایدرۆجین (Hydrogen) ژ بارکرنا باتریێن ئاسیدی (Lead-acid).","ئەڤ غازە ل گەرمیا ئاسایی غازن و ب هێسانی دگرن. سنوورێن تەقینێ ل هەوای: هایدرۆجین ٤-٧٥٪، پرۆپان ٢٫١-٩٫٥٪، ئەسیتیلین ژ ٢٫٥٪ و پتر. (-٢٥٣°C خالا کەلینا هایدرۆجینێ یە، نە خالا هەلبوونێ.)","گەرمیا گڕا ئۆکسی-ئەسیتیلین (Oxy-Acetylene) ژ ٣٠٠٠°C پترە.","ئەسیتیلین دگەل مسی (Copper) ماددەیەکێ تەقەمەنی چێدکەت (Copper Acetylide)؛ بۆری و ئامێرێن مسی یێن نەگونجای بکار نەئینە.","ڤەمراندن: ئێکەم، ئەگەر بێ مەترسی بیت، ڤالڤا غازێ بگرە. ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی هاتنا غازێ ڕاوەستینی — غازا دزەکری دشێت تەقینێ چێبکەت.","تیمێن ١١٥ سپرەیا ئاڤێ (Water Spray) ژ دوور بۆ سارکرنا سیلەندەر و تانکان بکار دئینن، نە بۆ ڤەمراندنا گڕا غازێ.","ئامێرێن ناسینا غازێ (Gas Detectors) ل کۆگەهێن غازێ: زەنگا ئاگەهداریێ دڤێت گەلەک بەری گەهشتنا LEL لێبدەت (ب گشتی ل ١٠-٢٠٪ یێن LEL).","ل کارگەهان: جهێن لەحیمکرنێ، جهێن بارکرنا فۆرکلیفتان، و ژوورێن باتریان."]},{heading:"٤. پۆلا D — کانزایێن سووتەنێ (NFPA 484)",body:"کانزایێن سووتەنێ — ئێک ژ مەترسیدارترین جۆران:",points:["سووتەمەنی: مەگنیسیۆم، تیتانیۆم، تۆزا ئەلەمنیۆمێ، سۆدیۆم، و لیتیۆمێ کانزایی (Lithium Metal).","ئەڤ کانزا ب گەرمیەکا گەلەک بلند دسوژن و ڕۆناهیەکا گەلەک توند ددەن؛ ڕاستەوخۆ بەرێ خوە نەدە گڕێ.","ئاڤ قەدەغەیە! Mg + H₂O → MgO + H₂ (هایدرۆجین پەیدا دبیت و دشێت بتەقیت).","CO₂ قەدەغەیە! 2Mg + CO₂ → 2MgO + C (مەگنیسیۆم د CO₂ دا ژی دسوژیت).","تەنێ تەمرینکێن پۆلا D، و تەنێ ئەو یا کو ناڤێ وی کانزای ل سەر لایبلا وێ هاتی: ماددە ژ کانزایەکێ بۆ یێ دی جودایە (بۆ نموونە تۆزا ل سەر بنەمایێ کلۆریدا سۆدیۆمێ (NaCl) یان گرافیت؛ تۆزا مسی بۆ لیتیۆمێ). چ جاران ئاڤ، تۆزا ئاسایی یان کەف بکار نەئینە. لمێ هشک تەنێ ئەگەر پلانا ئاگری یا جهی یان SDS یا کانزای ناڤێ وی بینیت و تەمام هشک بیت.","نموونە ل کارگەهان: هەلاندنا ئەلەمنیۆمێ، تراشکرنا مەگنیسیۆمێ، و باتریێن لیتیۆمێ کانزایی.","NFPA 484: هەلگرتن، مامەلەکرن، و پاراستنا کانزایێن سووتەنێ (ئێستا پشکەک ژ NFPA 660).","تۆزا ئەلەمنیۆمێ: مەترسیا تەقینا تۆزێ ژی هەیە (NFPA 654 / 660).","بەرسڤ: ئێکسەر گازی ١١٥ بکە و تەنێ تەمرینکا پۆلا D بکاربینە یا کو ناڤێ وی کانزای ل سەر لایبلا وێ هاتی. باتریێن لیتیۆم-ئایۆن (Li-ion) لیتیۆمێ کانزایی تێدا نینە و ب ئاڤێ سار دبن."]},{heading:"٥. تۆزا سووتەنێ — تەقینا تۆزێ (NFPA 654)",body:"مەترسیەکا کوژەر ل کارگەهان:",points:["پێنجگۆشەیا تۆزێ (Dust Pentagon): سووتەمەنی (تۆز) + ئۆکسجین + گەرمی + بەلاڤبوون د هەوای دا + جهێ داخستی.","سەرچاڤە: ئارد، شەکر، دار، خەلووز، تۆزا کانزایان، و پلاستیک.","کێمترین گەرمیا هەلبوونێ (MIT) ل دویڤ جۆرێ تۆزێ دگوهۆڕیت؛ ل SDS یان ئەنجامێن تاقیکرنا تۆزێ بنێڕە.","کێمترین چڕیا تەقینێ (MEC) ژی ل دویڤ جۆرێ تۆزێ دگوهۆڕیت؛ تۆزا بەلاڤ د هەوای دا هەمیشە مەترسیدارە.","تەقینا ئێکێ (Primary): د ناڤ ئامێرەکێ دا (وەک فلتەر یان ئاشی).","تەقینا دووێ (Secondary): تەقینا ئێکێ تۆزا ل سەر عەرد و ڕەف و بۆریان بلند دکەت، و تەقینەکا مەزنتر و کوژەرتر چێدبیت.","کێمکرنا مەترسیێ: سیستەمێن کۆمکرنا تۆزێ، دەرگەهێن ڤالاکرنا تەقینێ (Explosion Vents)، و سیستەمێن ڤەمراندنێ.","پاقژی: چینەکا تۆزێ ب ستویریا ٠٫٨ ملم (1/32 inch) ل سەر پتر ژ ٥٪ یێ ڕووبەرێ عەردی دشێت مەترسیێ پەیدا بکەت (NFPA 654 / OSHA).","نموونە: ل سالا ٢٠٠٨ ل کارگەها شەکری Imperial Sugar (ئەمریکا)، تەقینا تۆزا شەکری ١٤ کارگەر کوشتن (CSB).","ستاندارد: NFPA 654 (ئێستا NFPA 660) و OSHA 29 CFR 1910.272 (بۆ کۆگەهێن دانەوێلان)."]},{heading:"٦. قۆناغێن گەشەکرنا ئاگری ل کارگەهێ",body:"٤ قۆناغێن ستاندارد — ل کارگەهان ئاگر دشێت لەزتر بیت:",points:["دەستپێک (Incipient): ئاگرەکێ بچووک — کەسەکێ ڕاهێنان دیتی دشێت ب تەمرینکا دەستی یا گونجای ڤەمرینیت، پشتی دانا ئاگەهداریێ و گازیکرنا ١١٥، و ڕێکا دەرکەفتنێ ل پشت وی بیت؛ ئەگەر ئێکسەر ڤەنەمری، دەرکەڤە.","گەشەکرن (Growth): ئاگر و دوکێل ب لەز زێدە دبن و سپرینکلەر کار دکەن — دەرکەڤە و گازی ١١٥ بکە.","گەشەکرنا تەمام (Fully Developed): پشتی Flashover — تەنێ تیمێن ١١٥.","کێمبوون (Decay): سووتەمەنی کێم دبیت، بەلێ مەترسیا Backdraft و هەرفتنێ دمینیت.","ل کارگەهان، کۆگەهێن بلند، پالێت، و شلەمەنی دشێن ئاگری ب لەزتر ژ مالان بگەهیننە قۆناغا تەمام.","تانکێن غاز و شلەمەنیێن ب فشار ئەگەر ب ئاگری گەرم ببن دشێن ب BLEVE بتەقن — دەوروبەرێ ب لەز ڤالا بکە.","پلانا کارگەهێ دڤێت ڕێکا گەهشتنا تیمێن ١١٥ و جهێن ئاڤا ئاگرکوژیێ (Hydrants) ئامادە و ڤەکری بهێلیت.","چاڤدێرێ ئاگری پشتی کارێ گەرم (Hot Work): ل دەمێ کاری و کێمترین ١ دەمژمێر پشتی ب دوماهیک هاتنێ، پاشان چاڤدێری هەتا ٣ دەمژمێرێن دی ل دویڤ بڕیارا بەرپرسێ مۆلەتێ (NFPA 51B)."]},{heading:"٧. بارێ ئاگری (Fire Load) و هەلسەنگاندنا مەترسیێ",body:"پشکنینا مەترسیێ ل کارگەهێ:",points:["بارێ ئاگری (Fire Load Density — MJ/m²): بڕا وزەیا کو ماددەیێن سووتەنێ د هەر مەترەکێ چارگۆشە دا دشێن بدەن. تێکڕایێن EN 1991-1-2 (Eurocode 1):","• خانی (Dwelling): نێزیکی ٧٨٠ MJ/m²","• نڤیسینگەهـ (Office): نێزیکی ٤٢٠ MJ/m²","• کتێبخانە (Library): نێزیکی ١٥٠٠ MJ/m²","• کۆگەهـ و کارگەهـ: ل دویڤ ماددەیێن هەلگرتی دهێتە حسێبکرن و گەلەک جاران ژ ڤان بلندترە.","هەلسەنگاندنا مەترسیێ (Risk Assessment): مەترسی = ئەگەرا ڕوودانێ (Likelihood) × گرانیا ئەنجامی (Severity).","• کێم (Low): ب ڕێکارێن ئاسایی دهێتە کۆنترۆلکرن.","• ناڤنجی (Medium): پێدڤی ب کۆنترۆلێن زێدە و چاڤدێریێ.","• بلند (High): پێدڤی ب کارێ لەز بەری بەردەوامبوونا کاری.","• گەلەک بلند (Extreme): کار ڕادوەستیت هەتا مەترسی کێم دبیت.","بەرگریا دیوار و بانان دژی ئاگری (Fire Resistance Rating) ل دویڤ جۆر و بکارئینانا ئاڤاهی ژ کۆدێن ئاڤاهیسازیێ دهێتە دیارکرن (وەک NFPA 101 و NFPA 5000).","هەلسەنگاندنا مەترسیێن کارگەهێ (وەک HVA) ب کێمی سالێ جارەکێ و پشتی هەر گوهۆڕینەکا مەزن نوو بکە."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"تەقینا تۆزێ",description:"نمایشا تەقینا تۆزێ"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"خشتەیا پۆلێن ئاگری",description:"پۆلینکرنا ئاگری ل کارگەهان"}],quiz:[{question:"بۆ ئاگرێ پۆلا D، کیش تەمرینک گونجایە؟",options:[{text:"تۆزا ABC",correct:!1},{text:"ئاڤ",correct:!1},{text:"تەمرینکا پۆلا D یا کو ناڤێ وی کانزای ل سەر لایبلا وێ هاتی",correct:!0},{text:"CO₂",correct:!1}],explanation:"تەنێ تەمرینکا پۆلا D یان ماددەیەک یێ کو ناڤێ وی کانزایێ دسۆژیت ل سەر لایبلا وی هاتی گونجایە؛ ماددە ژ کانزایەکێ بۆ یێ دی جودایە. ئاڤ، CO₂، و تۆزا ABC بکار نەئینە."},{question:"BLEVE چ واتە یە؟",options:[{text:"زەنگا ئاگری",correct:!1},{text:"Boiling Liquid Expanding Vapor Explosion",correct:!0},{text:"سیستەمێ سپرینکلەری",correct:!1},{text:"پۆلا غازێ",correct:!1}],explanation:"BLEVE تەقینا تانکەکا ب فشار یا شلەمەنیێ یە دەمێ ب ئاگری گەرم دبیت و هەلم ب لەز بەلاڤ دبیت."},{question:"پێنجگۆشەیا تۆزێ (Dust Pentagon) چەند توخمان هەیە؟",options:[{text:"٣",correct:!1},{text:"٤",correct:!1},{text:"٥",correct:!0},{text:"٦",correct:!1}],explanation:"پێنج توخم: سووتەمەنی + ئۆکسجین + گەرمی + بەلاڤبوون + جهێ داخستی."},{question:"ئەسیتیلین دگەل مسی (Copper) چ پەیدا دکەت؟",options:[{text:"چ ناقەومیت",correct:!1},{text:"Copper Acetylide — ماددەیەکێ تەقەمەنی",correct:!0},{text:"پاقژکرن",correct:!1},{text:"گەرمیەکا کێم",correct:!1}],explanation:"ئەسیتیلین دگەل مسی ماددەیەکێ تەقەمەنی یێ هەستیار (Copper Acetylide) چێدکەت کو ب لێدان یان گەرمیێ دتەقیت."},{question:"تۆزا ئەلەمنیۆمێ (Aluminum Powder) کیش مەترسی هەیە؟",options:[{text:"تەنێ پۆلا A",correct:!1},{text:"پۆلا D و تەقینا تۆزێ",correct:!0},{text:"تەنێ غاز",correct:!1},{text:"چ مەترسی نینە",correct:!1}],explanation:"تۆزا ئەلەمنیۆمێ هەم کانزایێ سووتەنێ یە (پۆلا D) و هەم تۆزا سووتەنێ یە (NFPA 484 / 654، ئێستا NFPA 660)."},{question:"ل دویڤ EN 1991-1-2، تێکڕایا بارێ ئاگری ل خانیان (Dwelling) نێزیکی چەندە؟",options:[{text:"١٠٠ MJ/m²",correct:!1},{text:"٢٣٠ MJ/m²",correct:!1},{text:"٤٢٠ MJ/m²",correct:!1},{text:"٧٨٠ MJ/m²",correct:!0}],explanation:"تێکڕایا بارێ ئاگری ل خانیان نێزیکی ٧٨٠ MJ/m² یە، و ل نڤیسینگەهان نێزیکی ٤٢٠ MJ/m² (EN 1991-1-2، خشتەیا E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"سیستەمێن ڤەمراندنا ئاگری ل کارگەهان",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"تەمرینکێن دەستی و سیستەمێن جێگیر یێن ڤەمراندنا ئاگری ل کارگەهان",blocks:[{body:"کارگەهـ پێدڤی ب دوو ئاستێن ڤەمراندنا ئاگری نە: ١) تەمرینکێن دەستی (Portable Extinguishers) بۆ ئاگرێن بچووک د قۆناغا دەستپێکێ دا، ٢) سیستەمێن جێگیر (Fixed Suppression Systems) بۆ پاراستنا بەردەوام. ل دویڤ جۆرێ مەترسیێ: سپرینکلەر (NFPA 13)، کەف (NFPA 11 / 16)، CO₂ (NFPA 12)، تۆزا هشک (NFPA 17)، و Clean Agent (NFPA 2001). ئەڤ مۆدیولە ئەڤان سیستەمان و خشتەیا پشکنینێ ڕوون دکەت."},{heading:"١. تەمرینکێن دەستی — هەلبژارتن ل کارگەهێ",body:"٧ جۆرێن سەرەکی و خشتەیا هەلبژارتنێ:",points:["تۆزا ABC (Multi-purpose): بەلاڤترین جۆر بۆ کۆریدۆر و جهێن گشتی — A، B، C (نە D و K).","CO₂: بۆ تابلۆیێن کارەبێ و ژوورێن سێرڤەران — B، C.","کەف (AFFF / Foam): بۆ کۆگەهێن شلەمەنیان و جهێن دیوارێن ڕاگرتنێ — A، B.","Wet Chemical (کیمیایی یا شل): بۆ مەتبەخ و کافتریا کارگەهێ — K.","Clean Agent: بۆ ژوورێن سێرڤەر و کۆنترۆلێ.","پۆلا D (ماددەیەک یێ کو ناڤێ وی کانزایێ ل وێرێ بکار دهێت ل سەر لایبلا وی هاتی): بۆ تراشکرنا کانزایان و هەلاندنا ئەلەمنیۆمێ.","Water Mist (ئاڤا هوور یا بێ کانزا): بۆ A، و هندەک مۆدێل بۆ C — ل دویڤ لیستکرنا ئامێری.","ئاستێن مەترسیێ ل دویڤ NFPA 10 (کێمترین هەلسەنگاندنا تەمرینکا پۆلا A):","• مەترسیا کێم (Light Hazard — نڤیسینگەهـ): 2-A","• مەترسیا ئاسایی (Ordinary Hazard — کارگەها ئاسایی): 2-A","• مەترسیا زێدە (Extra Hazard — کارگەها ب سووتەمەنیا گەلەک): 4-A","دووراتیا گەهشتنێ (Travel Distance) هەتا تەمرینکێ:","• پۆلا A: هەتا ٢٣ مەتر (٧٥ پێ) ل هەمی ئاستان.","• پۆلا B: ٩ یان ١٥ مەتر (٣٠ / ٥٠ پێ) ل دویڤ هەلسەنگاندنا تەمرینکێ و ئاستێ مەترسیێ."]},{heading:"٢. سیستەمێن سپرینکلەری — NFPA 13",body:"گرنگترین سیستەمێ جێگیر ل گەلەک کارگەهان:",points:["٤ جۆرێن سیستەمێن سپرینکلەری:","• بۆریێن تەڕ (Wet Pipe): بۆری هەمیشە پڕ ئاڤن — بەرسڤا لەزترین و بەلاڤترین جۆر.","• بۆریێن هشک (Dry Pipe): بۆری پڕ هەوا یان نایترۆجینێ ب فشارن — بۆ جهێن کو گەرمی لێ دچیتە خوار ٤°C.","• پێش-کارکرن (Pre-action): ڤالڤ تەنێ پشتی ناسینا ئاگری ب دەتێکتەران ڤەدبیت، پاشان سەرێ سپرینکلەری ب گەرمیێ ڤەدبیت — بۆ جهێن ئامێرێن هەستیار.","• Deluge: سەرێن ڤەکری، و هەمی پێکڤە ئاڤێ دڕژینن — بۆ جهێن مەترسیا بلند.","پلەیا گەرمیا ڤەبوونێ (Activation Temperature) و ڕەنگێ گلۆپا شووشەیی:","• ٥٧°C (پرتەقالی): پلەیا ئاسایی (Ordinary) — جهێن گەرمیا وان نزم.","• ٦٨°C (سۆر): پلەیا ئاسایی (Ordinary) — بەلاڤترین ل نڤیسینگەهـ و کارگەهان.","• ٧٩°C (زەرد) و ٩٣°C (کەسک): پلەیا ناڤنجی (Intermediate) — جهێن گەرمتر.","• ١٤١°C (شین): پلەیا بلند (High) — ژوورێن بۆیلەران و نێزیکی ئامێرێن گەرم.","ڕووبەرێ پاراستنێ بۆ هەر سەرەکێ ئاسایی (Standard Spray): هەتا نێزیکی ٢١ m² (Light)، ١٢ m² (Ordinary)، و ٩ m² (Extra Hazard).","چڕیا ئاڤێ (Density): 0.10-0.40 gpm/ft² (نێزیکی ٤-١٦ mm/min) ل دویڤ ئاستێ مەترسیێ.","NFPA 25: پشکنین و تاقیکرن ب خشتەیێن هەفتیانە، هەیڤانە، سالانە، و ٥ سالان.","سپرینکلەر تەنێ ل جهێ ئاگری ڤەدبن؛ هەمی سەر پێکڤە ڤەنابن (ژ بلی سیستەمێ Deluge)."]},{heading:"٣. سیستەمێن کەفێ — NFPA 11 / 16",body:"بۆ کۆگەهێن مەزن یێن شلەمەنیان:",points:["٣ جۆرێن کەفێ ل دویڤ ڕێژەیا بەرفرەهبوونێ (Expansion):","• کێم (Low-Expansion، هەتا 20:1): ئاگرێن تانکان و ڕژانا شلەمەنیان.","• ناڤنجی (Medium-Expansion، 20:1 هەتا 200:1): جهێن دیوارێن ڕاگرتنێ.","• بلند (High-Expansion، 200:1 هەتا 1000:1): هەنگارێن فڕۆکەیان و جهێن مەزن یێن داخستی.","جۆرێن ماددەیێ کەفێ (Concentrate):","• AFFF: بۆ هایدرۆکاربۆنان (بەنزین، دیزل).","• AR-AFFF (Alcohol-Resistant): بۆ سۆلڤێنتێن پۆلار (ئەلکهول، ئەسیتۆن).","• Fluoroprotein: بۆ تانکێن هەلگرتنێ.","• کەفا بێ فلۆرین (Fluorine-Free Foam — F3): جێگرێ کەفێن PFAS.","ڕێژەیا بکارئینانێ (Application Rate):","• ڕژانا هایدرۆکاربۆنان: کێمترین نێزیکی ٤٫١ L/min/m² (0.10 gpm/ft²).","• سۆلڤێنتێن پۆلار: ل دویڤ لیستکرنا بەرهەمئینەری، ب گشتی بلندتر.","مەترسیا PFAS: AFFF ماددەیێن فلۆرینی (PFAS) تێدا هەنە کو د لەشی و ژینگەهێ دا کۆم دبن؛ گەلەک وەلات بەرەڤ کەفا بێ فلۆرین (F3) دچن.","ل کارگەهان: کۆمەلگەهێن تانکان، جهێن بارکرنا تانکەران، و پالاوگەهان."]},{heading:"٤. سیستەمێن CO₂ و Clean Agent — NFPA 12 / 2001",body:"بۆ ژوورێن ئامێران و تژیکرنا تەمام (Total Flooding):",points:["تژیکرنا تەمام ب CO₂:","• چڕیا دیزاینێ: کێمترین ٣٤٪ (NFPA 12)، و بۆ هندەک ماددەیان پتر.","• مەترسی: چڕیا ڤەمراندنێ بۆ مرۆڤان کوژەرە — چ کەس نابیت د ژووری دا بمینیت.","• زەنگا پێش-بەردانێ و دەمێ ڕاوەستانێ (Time Delay): دڤێت بەس بیت بۆ ڤالاکرنا ژووری بەری بەردانا غازێ (NFPA 12).","• بکارئینان: ژوورێن جەنەڕەیتەران، جهێن تاقیکرنا مەکینەیان، و ئامێرێن چاپێ.","Clean Agent (FK-5-1-12 / HFC-227ea):","• NOAEL: ل جهێن کەس لێ، چڕیا دیزاینێ ژ ئاستێ بێ زیان (NOAEL) نابۆریت (NFPA 2001)؛ دیسا ژی ژووری ڤالا بکە.","• چڕیا دیزاینێ: ب گشتی نێزیکی ٤-٩٪ ل دویڤ جۆرێ ماددەی.","• بەردان (Discharge): ماددەیێن هالۆکاربۆنی د ١٠ چرکەیان دا (NFPA 2001).","• بکارئینان: ژوورێن سێرڤەران، کۆنترۆلێ، و سویچان.","• بهایێ وێ ژ سیستەمێن ئاڤێ گەلەک بلندترە.","Halon 1301: بەرهەمئینانا وێ ل دویڤ پرۆتۆکۆلا مۆنترێال ژ ١٩٩٤ ڤە ل وەلاتێن پێشکەفتی هاتیە ڕاگرتن، چونکو چینا ئۆزۆنێ تێکددەت؛ سیستەمێن نوو پێ ناهێنە دانان.","تاقیکرنا هیدرۆستاتیکی یا تەمرینکێن دەستی (NFPA 10): CO₂ هەر ٥ سالان، Clean Agent هەر ١٢ سالان؛ سیلەندەرێن سیستەمێن جێگیر ل دویڤ NFPA 12 / 2001 و یاسایێن سیلەندەران."]},{heading:"٥. سیستەمێن تۆزا هشک — NFPA 17",body:"بۆ مەترسیێن تایبەت:",points:["سیستەمێن ئامادەکری (Pre-Engineered Systems):","• مەتبەخێن بازرگانی: ئێستا ب گشتی سیستەمێن Wet Chemical (NFPA 17A) دهێنە بکارئینان، نە تۆزا هشک.","• ژوورێن ڕەنگکرنێ (Spray Booths).","• پاراستنا ئامێر و ترومبێلێن گران.","• تانکێن نوقمکرنێ (Dip Tanks).","ماددە (Agents):","• بیکاربۆناتا سۆدیۆمێ (Sodium Bicarbonate): B، C.","• بیکاربۆناتا پۆتاسیۆمێ (Purple-K): B، C — ل سەر ئاگرێن پۆلا B ژ سۆدیۆمێ ب هێزترە.","• فۆسفاتا ئەمۆنیۆمێ (Monoammonium Phosphate): A، B، C.","• کلۆریدا پۆتاسیۆمێ (Potassium Chloride): B، C.","ڤەبوون (Activation): دەتێکتەرێ گەرمیێ یان دەستگرەکێ دەستی (Manual Pull).","پشتی بەردانێ: تۆز ل هەمی جهان بەلاڤ دبیت و دشێت زیانێ بگەهینیتە ئامێرێن ئەلکترۆنی؛ پاقژکرن گرانە.","ڕووبەرێ پاراستنێ یێ هەر لۆلەکێ (Nozzle) ل دویڤ لیستکرنا سیستەمی دهێتە دیارکرن."]},{heading:"٦. ناسینا ئاگری — NFPA 72",body:"سیستەمێ ناسینێ — هێلا ئێکێ یا ئاگەهدارکرنێ:",points:["جۆرێن دەتێکتەران:","• دوکێل: فۆتۆئەلکتریک (Photoelectric) بۆ ئاگرێن هێدی (Smoldering)، ئایۆنیزەیشن (Ionization) بۆ ئاگرێن ب گڕ (Flaming).","• گەرمی: پلەیا جێگیر (Fixed Temperature، وەک ٥٧°C) یان بلندبوونا لەز (Rate-of-Rise).","• گڕ (Flame): UV/IR — گڕێ ب لەز دناسن.","• غاز: دەتێکتەرێن LEL و سێنسۆرێن CO.","• کێشانا نموونەیێن هەوای (Air-Sampling): بۆ ژوورێن سێرڤەران — هەستیارترین جۆر.","دووراتی و ڕووبەر:","• دوکێل: دووراتیا ناڤبەرا دەتێکتەران نێزیکی ٩ مەتر (30 ft) ل سەر بانێ ڕێک (NFPA 72).","• گەرمی: ل دویڤ دووراتیا لیستکری یا دەتێکتەری (Listed Spacing).","• گڕ: ل دویڤ گۆشەیا دیتنێ و دووراتیا لیستکری یا ئامێری.","ئاگەهدارکرن (Alarm Notification):","• دەنگ (Audible): ب گشتی کێمترین ١٥ dB ژ تێکڕایا دەنگێ جهی بلندتر (NFPA 72).","• ڕۆناهی (Strobe): بۆ جهێن ب دەنگەدەنگ و بۆ کەسێن کێماسیا بهیستنێ هەی.","• ئاگەهدارکرنا دەنگی (Voice / Mass Notification): بۆ ئاڤاهی و کارگەهێن مەزن.","پشکنین و تاقیکرن: ل دویڤ خشتەیێن NFPA 72 (گەلەک ئامێر سالێ جارەکێ دهێنە تاقیکرن)."]},{heading:"٧. خشتەیا پشکنین و ساخکرنێ",body:"ل دویڤ ستانداردێن NFPA:",points:["ڕۆژانە / هەفتیانە:","• پشکنینا چاڤی (فشارا گەیجان، زیان).","• پشکنینا هندێ کو چ تشت نەکەفتبنە بەر سپرینکلەران.","• هەلکرنا ئاگرپەمپێ بێی ڤەکرنا ئاڤێ (No-flow Test): پەمپا دیزلی هەر هەفتی، یا کارەبێ ب گشتی هەر هەیڤ (NFPA 25).","هەیڤانە:","• پشکنینا چاڤی یا تەمرینکێن دەستی (NFPA 10).","• پشکنینا پانێلا زەنگا ئاگری و نیشانێن خەلەتیێ (Trouble).","• پشکنینا دوگمێن زەنگێ (Manual Pull Stations) — دیار و نەگرتی.","سالانە:","• ساخکرنا سالانە یا تەمرینکێن دەستی ژ لایێ کەسێ شارەزا ڤە (نە تاقیکرنا هیدرۆستاتیکی).","• پشکنینا سپرینکلەران ژ سەر عەردی (NFPA 25).","• نموونەیا ماددەیێ کەفێ بۆ تاقیکرنێ.","• تاقیکرنا دەتێکتەر و زەنگان (NFPA 72).","هەر چەند سالان جارەکێ:","• تاقیکرنا هیدرۆستاتیکی یا تەمرینکان (تاقیکرنا فشارێ یا لەشێ وان، NFPA 10): هەر ٥ سالان بۆ ئاڤ، کەف، Wet Chemical، CO₂ و تۆزا هشک یا ستێنلێس ستیل (stainless steel)؛ هەر ١٢ سالان بۆ تۆزا هشک یا فشارا هەلگرتی (stored-pressure) یا لەشێ وێ ژ ئاسنێ نەرم (mild steel)، مسێ زەرد یێ لحیمکری (brazed brass) یان ئەلەمنیۆمێ، و بۆ Clean Agent. ب جودا، هەر ٦ سالان، تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی یێن کو پێدڤی ب تاقیکرنا ١٢ سالان هەی، ژ لایێ کەسێ شارەزا ڤە ڤالا دکەن و ناڤا وان دپشکنن. ڕێسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن.","• پشکنینا ناڤخوەیی یا بۆریێن سپرینکلەری: هەر ٥ سالان (NFPA 25).","• گوهۆڕین یان تاقیکرنا نموونەیێن سەرێن سپرینکلەری پشتی ٥٠ سالان (سەرێن ئاسایی — NFPA 25).","تۆمارکرن: هەمی پشکنین و تاقیکرنان بنڤیسە و تۆماران ل دویڤ ستانداردان و داخوازا دەزگەهێن پەیوەندیدار بپارێزە."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"ڤەبوونا سپرینکلەری",description:"نمایشا سپرینکلەری"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"خشتەیا سیستەمێن ڤەمراندنێ",description:"سیستەمێن جێگیر"}],quiz:[{question:"بۆ پترییا کارگەهان، گرنگترین سیستەمێ جێگیر کیژە؟",options:[{text:"تەمرینکێن دەستی",correct:!1},{text:"سپرینکلەر (NFPA 13)",correct:!0},{text:"تەنێ CO₂",correct:!1},{text:"چ ژ ڤان",correct:!1}],explanation:"سپرینکلەر ب خوە کار دکەن و ئاگری د قۆناغا دەستپێکێ دا کۆنترۆل دکەن، حەتا دەمێ کەس ل جهی نەبیت؛ تەمرینکێن دەستی تەنێ بۆ ئاگرێن بچووکن."},{question:"سیستەمێ بۆریێن تەڕ (Wet Pipe) بۆ کیش جهی نەگونجایە؟",options:[{text:"ژوورێن ئامێران (ICT)",correct:!1},{text:"نڤیسینگەهـ",correct:!1},{text:"جهێن کو گەرمی لێ دچیتە خوار ٤°C",correct:!0},{text:"کۆگەهـ",correct:!1}],explanation:"ل جهێن سار ئاڤ د بۆریان دا دقەریسیت؛ سیستەمێ بۆریێن هشک (Dry Pipe) گونجایە."},{question:"ئەرێ سیستەمێن نوو ب Halon 1301 دهێنە دانان؟",options:[{text:"بەلێ",correct:!1},{text:"نەخێر — بەرهەمئینانا وێ ل دویڤ پرۆتۆکۆلا مۆنترێال هاتیە ڕاگرتن",correct:!0},{text:"تەنێ ل ژوورێن ICT",correct:!1},{text:"تەنێ ل ژوورێن سێرڤەران",correct:!1}],explanation:"Halon 1301 چینا ئۆزۆنێ تێکددەت؛ بەرهەمئینانا وێ ل وەلاتێن پێشکەفتی ژ ١٩٩٤ ڤە هاتیە ڕاگرتن."},{question:"بۆچی دڤێت هەمی کەس بەری بەردانا سیستەمێ CO₂ یێ تژیکرنا تەمام ژ ژووری دەرکەڤن؟",options:[{text:"پێدڤی ناکەت، CO₂ بێ زیانە",correct:!1},{text:"چونکو چڕیا ڤەمراندنێ (٣٤٪ و پتر) بۆ مرۆڤان کوژەرە",correct:!0},{text:"چونکو CO₂ ئاڤێ دڕژینیت",correct:!1},{text:"چونکو CO₂ دەنگەکێ بلند پەیدا دکەت",correct:!1}],explanation:"چڕیا دیزاینا CO₂ ل سیستەمێن تژیکرنا تەمام کێمترین ٣٤٪ ە (NFPA 12)، و ئەڤ چڕییە د دەمەکێ کورت دا مرۆڤی بێهۆش دکەت و دکوژیت؛ ژبەرهندێ زەنگا پێش-بەردانێ و دەمێ ڕاوەستانێ هەنە."},{question:"ڕووبەرێ پاراستنێ یێ هەر سەرەکێ سپرینکلەری (Standard Spray) نێزیکی چەندە؟",options:[{text:"٢-٥ m²",correct:!1},{text:"١٢-٢١ m²",correct:!0},{text:"٥٠ m²",correct:!1},{text:"١٠٠ m²",correct:!1}],explanation:"ل دویڤ NFPA 13: نێزیکی ٢١ m² بۆ مەترسیا کێم و ١٢ m² بۆ مەترسیا ئاسایی؛ بۆ مەترسیا زێدە کێمترە (نێزیکی ٩ m²)."},{question:"تاقیکرنا هەفتیانە یا ئاگرپەمپا دیزلی چ کارە؟",options:[{text:"تەنێ پشکنینا چاڤی",correct:!1},{text:"هەلکرنا پەمپێ بێی ڤەکرنا ئاڤێ (Start / No-flow Test)",correct:!0},{text:"تاقیکرنا هیدرۆستاتیکی",correct:!1},{text:"چ ژ ڤان",correct:!1}],explanation:"NFPA 25: پەمپا دیزلی هەر هەفتی و پەمپا کارەبێ ب گشتی هەر هەیڤ بێی ڤەکرنا ئاڤێ دهێتە هەلکرن و تاقیکرن."}]}],t={lessons:e};export{t as default,e as lessons};
